function accountIcon(name){const icons={"bookmark": "<svg\n  xmlns=\"http://www.w3.org/2000/svg\"\n  width=\"24\"\n  height=\"24\"\n  viewBox=\"0 0 24 24\"\n  fill=\"none\"\n  stroke=\"currentColor\"\n  stroke-width=\"2\"\n  stroke-linecap=\"round\"\n  stroke-linejoin=\"round\"\n  class=\"icon icon-tabler icons-tabler-outline icon-tabler-bookmark\"\n>\n  <path stroke=\"none\" d=\"M0 0h24v24H0z\" fill=\"none\"/>\n  <path d=\"M18 7v14l-6 -4l-6 4v-14a4 4 0 0 1 4 -4h4a4 4 0 0 1 4 4z\" />\n</svg>", "clock": "<svg\n  xmlns=\"http://www.w3.org/2000/svg\"\n  width=\"24\"\n  height=\"24\"\n  viewBox=\"0 0 24 24\"\n  fill=\"none\"\n  stroke=\"currentColor\"\n  stroke-width=\"2\"\n  stroke-linecap=\"round\"\n  stroke-linejoin=\"round\"\n  class=\"icon icon-tabler icons-tabler-outline icon-tabler-clock\"\n>\n  <path stroke=\"none\" d=\"M0 0h24v24H0z\" fill=\"none\"/>\n  <path d=\"M3 12a9 9 0 1 0 18 0a9 9 0 0 0 -18 0\" />\n  <path d=\"M12 7v5l3 3\" />\n</svg>"};return icons[name]||''}
const adImages={"audio": "data:image/svg+xml;base64,", "coffee": "data:image/svg+xml;base64,", "travel": "data:image/svg+xml;base64,", "sport": "data:image/svg+xml;base64,", "home": "data:image/svg+xml;base64,", "learning": "data:image/svg+xml;base64,"};
let searchHistoryCache;
let floatingAdClosed=false;
let catalog, movies=[], heroIndex=1, heroTimer, adTimer, listState={}, currentMovie=null, episode=1, localVideo=null;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k)=>{try{return JSON.parse(localStorage.getItem('sa-'+k)||'[]')}catch{return []}};
const save=(k,v)=>localStorage.setItem('sa-'+k,JSON.stringify(v));
const catIds={'全部分类':'','电影':'13','连续剧':'12','综艺':'11','短剧':'16','动漫':'14','纪录片':'15'};
const listUrl=(cat='')=>'/movie/list?cat_id='+(catIds[cat]||cat)+'&position=movie';
const movieUrl=m=>'/movie/detail/'+(m.slug||m.id)+'-'+m.id;
function toast(s){$('#toast').classList.remove('feedback-success','invite-toast');$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',3000)}
function categoryMenu(){return Object.keys(catIds).map(c=>{const tags=[...new Set(movies.filter(m=>!catIds[c]||m.category===c).flatMap(m=>m.tags?.map(t=>t.name)||[]))];const links=c==='全部分类'?Object.keys(catIds).filter(x=>catIds[x]).map(x=>[x,listUrl(x)]):tags.map(t=>[t,listUrl(c)+'&tag='+encodeURIComponent(t)]);return `<div class="nav-category"><a class="nav-category-link" href="${listUrl(c)}">${c}<span aria-hidden="true">›</span></a><section class="nav-submenu" aria-label="${c}二级菜单"><div class="nav-submenu-heading">${c}<a href="${listUrl(c)}">查看全部 ›</a></div><div class="nav-submenu-links">${links.map(([label,url])=>`<a href="${esc(url)}">${esc(label)}</a>`).join('')||`<a href="${listUrl(c)}">全部${c}</a>`}</div></section></div>`}).join('')}

const appCategories=['推荐','游戏','工具','福利','任务'];
const appIconX=[36,102,168,233,299,365,430,496,562,628,694,760,825,891,957,1023];
const centerApps=Array.from({length:80},(_,i)=>({id:'app-'+(i+1),name:'应用 '+String(i+1).padStart(2,'0'),category:appCategories[1+Math.floor(i/16)%4],icon:i%16}));
function appIcon(a){return `<span class="app-tile-icon" aria-hidden="true" style="background-position:${appIconX[a.icon]/1045*100}% ${62/441*100}%"></span>`}
let appPromotionClosed=false;
function appCenterFooter(){const app=centerApps[0];return `<div class="app-center-promotions">${homeAdRow(0)}${appPromotionClosed?'':`<aside class="app-promotion" aria-label="推荐应用"><div class="app-promotion-icon">${appIcon(app)}</div><div class="app-promotion-copy"><span>精选推荐</span><h2>${esc(app.name)}</h2></div><button class="app-promotion-view" type="button" data-center-app="${app.id}">查看</button><button class="app-promotion-close" type="button" data-close-app-promotion aria-label="关闭应用推荐">×</button></aside>`}</div>`}
document.addEventListener('click',e=>{if(e.target.closest('[data-close-app-promotion]')){appPromotionClosed=true;e.target.closest('.app-promotion').remove()}});
function appCenter(){const requested=new URLSearchParams(location.search).get('category'),category=appCategories.includes(requested)?requested:'推荐',items=category==='任务'?[]:category==='推荐'?centerApps:centerApps.filter(a=>a.category===category);document.title='应用中心 - 万象';$('#app').innerHTML=`${heroBanner()}<div class="app-center"><h1 class="sr-only">应用中心</h1><nav class="app-category-tabs" aria-label="应用分类">${appCategories.map(c=>`<a href="/apps?category=${encodeURIComponent(c)}" class="${c===category?'selected':''}" ${c===category?'aria-current="page"':''}>${c}</a>`).join('')}</nav><div class="app-center-grid">${items.map(a=>`<button class="app-tile" type="button" data-center-app="${a.id}" aria-label="查看${a.name}">${appIcon(a)}<span class="app-tile-name">${a.name}</span></button>`).join('')||'<div class="rank-empty app-task-empty" role="status"><img src="/assets/app-task-empty.png" alt=""><p>阿偶，没有找到您想要的内容哦~</p></div>'}</div>${appCenterFooter()}</div>`;startHeroCarousel();initHomeAds();startHomeAds()}
function showCenterApp(id){const a=centerApps.find(x=>x.id===id);if(!a)return;openModal(`<section class="app-detail"><div class="app-detail-heading">${appIcon(a)}<div><h2>${a.name}</h2><span class="content-tag">${a.category}</span></div></div><p class="muted">此应用为展示示例，暂未提供应用地址。</p><button class="primary" type="button" disabled>暂未开放</button></section>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-center-app]');if(b)showCenterApp(b.dataset.centerApp)});

function header(home=false){
$('#header').className=home?'home-header':'';document.body.classList.toggle('is-home',home);
const selected=new URLSearchParams(location.search).get('cat_id');
$('#header').innerHTML=`<div class="utility-row"><a class="search-brand" href="/" aria-label="万象首页"><img src="${catalog.logo}" alt="万象出品"></a><button class="search-capsule" data-action="mobile-search"><img src="/assets/h5-search.png" alt="">搜索影片、演员</button><a class="utility-icon" href="/mine/favorites" aria-label="我的收藏">${accountIcon('bookmark')}</a><a class="utility-icon" href="/mine/history" aria-label="观看记录">${accountIcon('clock')}</a></div>${(['/apps','/movie/rank'].includes(location.pathname)||location.pathname.startsWith('/mine'))?'':`<div class="header-inner"><a class="logo" href="/" aria-label="万象首页"><img src="${catalog.logo}" alt="万象出品"></a><nav class="h5-tabs" aria-label="影片导航"><a href="/" class="${home?'selected':''}">精选</a>${['电影','连续剧','综艺','动漫','纪录片','短剧'].map(c=>`<a class="${selected===catIds[c]?'selected':''}" href="${listUrl(c)}">${c==='连续剧'?'电视剧':c}</a>`).join('')}</nav><button class="h5-search" data-action="mobile-search" aria-label="搜索影片"><img src="/assets/h5-search.png" alt=""></button><a class="all-channels-link" href="${listUrl()}" aria-label="全部菜单">全部<span aria-hidden="true">›</span></a></div>`}`;
$('#footer').innerHTML=`<nav class="bottom-nav" aria-label="底部导航"><a href="/" class="${home?'selected':''}"><span aria-hidden="true">⌂</span>首页</a><a href="/movie/rank" class="${location.pathname==='/movie/rank'?'selected':''}"><span aria-hidden="true">♨</span>热播</a><button class="bottom-vip" data-action="vip"><img src="/vip-gift.png" alt=""><small>会员</small></button><a href="/apps" class="${location.pathname==='/apps'?'selected':''}"><span aria-hidden="true">应用</span>应用中心</a><a href="/mine" class="${location.pathname.startsWith('/mine')?'selected':''}"><span aria-hidden="true">♙</span>个人中心</a></nav>`;
}
function contentTags(m,limit=2){const labels=[...new Set((m.tags||[]).map(t=>t.name).filter(Boolean).concat(m.category||[]))];return `<span class="content-tags" aria-label="内容标签">${labels.slice(0,limit).map(label=>`<span class="content-tag">${esc(label)}</span>`).join('')}</span>`}
function card(m){return `<article class="movie-card"><a href="${movieUrl(m)}" aria-label="查看${esc(m.name)}"><div class="poster"><img src="${m.img}" alt="${esc(m.name)}" loading="lazy" decoding="async"><span class="score">${esc(m.score)}</span><span class="duration">${esc(m.duration)}</span><span class="hover-play" aria-hidden="true">▶</span></div><span class="card-title">${esc(m.name)}</span></a><div class="hover-info"><a class="hover-cover" href="${movieUrl(m)}" aria-label="查看${esc(m.name)}详情"><img src="${m.img}" alt="${esc(m.name)}" loading="lazy"></a><div class="hover-info-copy"><h3>${esc(m.name)}</h3><p>${contentTags(m)}　${esc(m.issue_year||m.issue_date?.slice(0,4)||'')}</p><p class="synopsis">${esc(m.description||'暂无简介')}</p><div><button data-fav="${m.id}">☆ 收藏</button><a href="${movieUrl(m)}">详情 ›</a></div></div></div><p class="card-meta">${contentTags(m)}</p></article>`}
function section(s,i,feature=false){return `<section class="${feature?'feature-section':'catalog-section'}"><div class="section-title">${s.icon?`<img src="${s.icon}" alt="">`:''}<h2>${esc(s.name)}</h2>${feature?'':`<a class="more" href="${listUrl(s.items[0]?.category)}">更多 ›</a>`}</div><div class="${feature?'feature-track':'movie-grid'}" id="row-${i}">${s.items.map(card).join('')}</div>${feature?`<button class="row-arrow prev" data-row="${i}" data-step="-1" aria-label="上一张">‹</button><button class="row-arrow next" data-row="${i}" data-step="1" aria-label="下一张">›</button>`:''}</section>`}
function heroBanner(){const b=catalog.banners[heroIndex];return `<section class="hero" aria-label="推荐影片轮播"><a id="hero-link" href="${bannerLink(b)}"><img class="hero-image" src="${b.content}" alt="${esc(b.name)}" fetchpriority="high"></a><div class="hero-copy">${heroCopy(b)}</div><div class="hero-picker"><button type="button" class="banner-step" data-hero-step="-1" aria-label="上一部推荐影片">‹</button><div class="hero-thumbs" aria-label="选择推荐影片">${catalog.banners.map((x,i)=>`<button class="hero-thumb ${i===heroIndex?'active':''}" aria-pressed="${i===heroIndex}" aria-label="切换到${esc(x.name)}" data-slide="${i}"><span class="hero-caption">${esc(x.name)}</span></button>`).join('')}</div><button type="button" class="banner-step" data-hero-step="1" aria-label="下一部推荐影片">›</button></div></section>`}
function home(){header(true);
$('#app').innerHTML=`${heroBanner()}<div class="home-content"><section class="topic-discovery" aria-labelledby="topic-heading"><div class="topic-heading"><h2 id="topic-heading"><img class="topic-flame" src="/assets/topic-flame-new.png" alt="" width="24" height="24">热门专题</h2></div><nav class="topic-rail" aria-label="推荐主题">${catalog.themes.map(t=>`<a href="/theme-detail/${t.id}"><span>${esc(t.name)}</span><span class="topic-chevron" aria-hidden="true">›</span></a>`).join('')}</nav></section>${[...catalog.home_recommends,...catalog.sections].map((s,i,all)=>section(s,i,i<catalog.home_recommends.length)+(i<all.length-1?homeAdRow(i+1):'')).join('')}</div>`;
if(!floatingAdClosed)$('#app').insertAdjacentHTML('beforeend',`<aside class="home-floating-ad" aria-label="浮窗广告"><button class="floating-ad-link" type="button" data-commercial-ad="audio" aria-label="查看广告"><img src="/assets/detail-ad.png" alt="推广广告" width="88" height="88"><span>广告</span></button><button class="floating-ad-close" type="button" aria-label="关闭浮窗广告" data-close-floating-ad>×</button></aside>`);
initHomeAds();startHomeAds();
startHeroCarousel();
}
function startHeroCarousel(){clearInterval(heroTimer);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)heroTimer=setInterval(()=>{const hero=$('.hero');if(hero&&!hero.matches(':hover')&&!hero.contains(document.activeElement)&&!document.hidden)slide(heroIndex+1)},7000);}
function bannerLink(b){if(b.link.startsWith('/movie/detail/')){const m=movies.find(m=>b.link.endsWith(m.id));if(m)return movieUrl(m);return '/search?q='+encodeURIComponent(b.name)}return b.link.startsWith('/movie/list')?b.link:listUrl('动漫')}
function bannerMovie(b){return movies.find(m=>b.link.endsWith(m.id))}
function heroCopy(b){const m=bannerMovie(b);const facts=m?[m.score&&m.score!=='0.0'?`★ ${m.score} 分`:null,m.heat?`热度 ${m.heat}`:null,m.duration].filter(Boolean):[];const meta=m?[m.actor?.split(/[,，、/]/).slice(0,2).join('　'),''].filter(Boolean).join('　'):'';return `<h1>${esc(b.name)}</h1>${facts.length?`<div class="hero-facts">${facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div>`:''}${m?`<p class="hero-meta">${esc(meta)} ${contentTags(m,Infinity)}</p>`:''}<p class="hero-tagline">${esc(b.tag_text||m?.description||b.description||'精选影片，精彩呈现')}</p><a class="play-button" href="${bannerLink(b)}"><span aria-hidden="true">▶</span>立即播放</a>`}
function slide(i){heroIndex=(i+catalog.banners.length)%catalog.banners.length;const b=catalog.banners[heroIndex];if(!$('.hero'))return;$('.hero-image').src=b.content;$('.hero-image').alt=b.name;$('#hero-link').href=bannerLink(b);$('.hero-copy').innerHTML=heroCopy(b);document.querySelectorAll('[data-slide]').forEach(e=>{const active=+e.dataset.slide===heroIndex;e.classList.toggle('active',active);e.setAttribute('aria-pressed',String(active));if(active){const rail=$('.hero-thumbs');if(e.offsetLeft<rail.scrollLeft||e.offsetLeft+e.offsetWidth>rail.scrollLeft+rail.clientWidth)rail.scrollTo({left:e.offsetLeft,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}})}
function route(){window.clearPageSkeleton?.();clearInterval(heroTimer);clearInterval(adTimer);if(localVideo){URL.revokeObjectURL(localVideo);localVideo=null;}const path=location.pathname;currentMovie=null;document.body.classList.toggle('is-search',path==='/search');document.body.classList.toggle('is-apps',path==='/apps');document.body.classList.toggle('is-rank',path==='/movie/rank');document.body.classList.toggle('is-profile',path==='/mine');document.body.classList.toggle('is-mine-list',path.startsWith('/mine/'));document.body.classList.toggle('is-detail',path.startsWith('/movie/detail/'));document.body.classList.toggle('is-theme-detail',path.startsWith('/theme-detail/'));document.body.classList.toggle('is-category-page',path==='/movie/list');document.title='万象';if(path==='/')home();else{header();if(path.startsWith('/movie/detail/'))detail(path);else if(path==='/movie/rank')rank();else if(path==='/apps')appCenter();else if(path.startsWith('/theme-detail/'))themePage(path);else if(path==='/search'){searchPage()}else if(path==='/movie/list')listing();else if(path==='/mine')profilePage();else if(path.startsWith('/mine/'))mine(path);else $('#app').innerHTML='<div class="empty"><h1>页面不存在</h1><p>这个链接暂时没有对应内容。</p><a class="primary" href="/">返回首页</a></div>';}document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.style.opacity='.25';img.alt='图片暂时无法加载'},{once:true}))}
function searchPage(){
const q=new URLSearchParams(location.search).get('q')||'';
$('#header').innerHTML=`<div class="search-page-bar"><a href="/" class="search-back" aria-label="返回首页"><img class="page-back-icon" src="/assets/page-back.svg" width="24" height="24" alt=""></a><form class="search-form search-page-form" role="search"><div class="search-input-wrap"><img src="/assets/h5-search.png" alt="" width="20" height="20"><input name="q" aria-label="搜索影片" placeholder="万象站内搜索" value="${esc(q)}" autocomplete="off" enterkeyhint="search"></div><button class="search-submit" type="submit">搜索</button></form></div>`;
if(q){listing();return}
document.title='搜索 - 万象';
$('#app').innerHTML=`<div class="search-discovery"><h1 class="sr-only">搜索影片</h1>${homeAdRow(0)}${searchPageHistory()}<section class="search-trending" aria-labelledby="trending-title"><h2 id="trending-title"><img src="/assets/topic-flame.png" alt="" width="24" height="24">大家都在搜</h2><ol>${['醒来','交锋','重器','凡人修仙传','哪吒之魔童闹海'].map((name,i)=>`<li><a href="/search?q=${encodeURIComponent(name)}"><span class="trending-number">${i+1}</span><span>${name}</span><span class="trending-chevron" aria-hidden="true">›</span></a></li>`).join('')}</ol></section></div>`;
initHomeAds();startHomeAds();
}
function openModal(body){const d=$('#modal');d.classList.remove('navigation-drawer','filter-tags-modal','speed-modal','episodes-modal','line-modal','feedback-sheet','official-group-modal','identity-modal','cache-modal','redeem-modal');d.removeAttribute('aria-labelledby');d.removeAttribute('aria-describedby');d.innerHTML='<button class="close-modal" aria-label="关闭" data-action="close">×</button>'+body;if(!d.open)d.showModal()}
let demoAccount='';
const demoRegisteredAccounts=new Set();
function registrationErrors(account,password,confirm){return {account:!/^[A-Za-z0-9]{4,10}$/.test(account)?'账号4–10位，仅限英文、数字或组合；':demoRegisteredAccounts.has(account.toLowerCase())?'该账号已被注册，请更换；':'',password:!/^(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9]).{6,8}$/.test(password)?'密码6–8位，包含大小写字母和数字；':'',confirm:!confirm?'请再次输入密码；':confirm!==password?'两次输入的密码不一致':''}}
function authFieldError(name){return `<p id="auth-${name}-error" class="auth-field-error" aria-live="polite" hidden></p>`}
function login(mode='login'){if(demoAccount&&mode==='login'){navigate('/mine');return}const register=mode==='register';openModal(`<section class="auth-panel" aria-labelledby="auth-title"><div class="auth-heading"><img class="auth-logo" src="${esc(catalog.logo)}" alt="万象出品"><h2 id="auth-title">${register?'注册账号':'欢迎登录'}</h2><p>${register?'创建账号，开启您的观影时光':'欢迎回来，请登录您的账号'}</p></div><form id="login-form" data-mode="${mode}"><label for="auth-account">账号</label><input id="auth-account" name="account" autocomplete="username" placeholder="${register?'账号4–10位、仅限英文、数字或组合':'请输入账号'}" required maxlength="40">${register?authFieldError('account'):''}<label for="auth-password">密码</label><div class="auth-password"><input id="auth-password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'密码6–8位，包含大小写字母和数字':'请输入密码（至少6位）'}" required minlength="6" maxlength="128"><button type="button" class="password-toggle" data-password-toggle="auth-password" aria-label="显示密码" aria-pressed="false">${passwordEye(false)}</button></div>${register?authFieldError('password'):''}${register?`<label for="auth-confirm">确认密码</label><div class="auth-password"><input id="auth-confirm" name="confirm" type="password" autocomplete="new-password" placeholder="请再次输入密码" required minlength="6" maxlength="128"><button type="button" class="password-toggle" data-password-toggle="auth-confirm" aria-label="显示确认密码" aria-pressed="false">${passwordEye(false)}</button></div>${authFieldError('confirm')}`:''}<p class="auth-switch">${register?'已有账号？':'还没有账号？'} <button type="button" data-auth-mode="${register?'login':'register'}">${register?'立即登录':'立即注册'}</button></p><p class="error" id="login-error" role="alert" hidden></p><button type="submit" class="primary auth-submit" disabled>${register?'注册':'登录'}</button></form></section>`)}
function passwordEye(visible){return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>${visible?'':'<path d="M3 3l18 18"/>'}</svg>`}
function syncAuthForm(form){const account=form.querySelector('[name=account]'),password=form.querySelector('[name=password]'),confirm=form.querySelector('[name=confirm]');if(form.dataset.mode==='register'){const errors=registrationErrors(account.value,password.value,confirm.value);for(const input of [account,password,confirm]){const message=errors[input.name],show=input.dataset.touched==='true'&&!!message;const error=form.querySelector('#auth-'+input.name+'-error');error.textContent=show?message:'';error.hidden=!show;input.setAttribute('aria-invalid',String(show));input.setAttribute('aria-describedby',error.id);input.setCustomValidity(message)}form.querySelector('.auth-submit').disabled=form.dataset.busy==='true'||Object.values(errors).some(Boolean)}else{form.querySelector('.auth-submit').disabled=!account.value.trim()||password.value.length<6||!password.value.trim()}form.querySelector('#login-error').hidden=true;}
document.addEventListener('focusout',e=>{if(e.target.matches('#login-form input')){e.target.dataset.touched='true';syncAuthForm(e.target.closest('form'))}});
document.addEventListener('input',e=>{if(e.target.matches('#login-form input')){e.target.dataset.touched='true';syncAuthForm(e.target.closest('form'))}});
document.addEventListener('click',e=>{const mode=e.target.closest('[data-auth-mode]');if(mode){login(mode.dataset.authMode);return}const b=e.target.closest('[data-password-toggle]');if(!b)return;const input=document.getElementById(b.dataset.passwordToggle),visible=input.type==='password';input.type=visible?'text':'password';b.setAttribute('aria-pressed',String(visible));b.setAttribute('aria-label',(visible?'隐藏':'显示')+(input.name==='confirm'?'确认密码':'密码'));b.innerHTML=passwordEye(visible);input.focus();});

function listing(){const p=new URLSearchParams(location.search);listState={cat:p.get('cat_id')?.split(',')[0]||'',tag:p.get('tag')||'',area:p.get('area')||'',language:p.get('language')||'',year:p.get('year')||'',status:p.get('status')||'',sort:p.get('sort')||'',q:p.get('q')||'',page:Math.max(1,+(p.get('page')||1))};renderListing()}
const filterDialogOptions={};
function filterRow(label,key,values){
filterDialogOptions[key]={label,values};
const button=([label,value])=>`<button type="button" data-filter="${key}" data-value="${esc(value)}" aria-pressed="${listState[key]===value}" class="${listState[key]===value?'selected':''}">${esc(label)}</button>`;
const many=values.length>8;const preview=values.slice(0,5);const selected=values.find(x=>x[1]===listState[key]);if(selected&&!preview.some(x=>x[1]===selected[1]))preview.push(selected);
return `<div class="filter-row ${many?'filter-row-many':''}"><span class="filter-label">${label}</span><div class="filter-options-wrap"><div class="filter-options">${(many?preview:values).map(button).join('')}</div>${many?`<button type="button" class="filter-expansion filter-expand-button" data-open-filter="${key}" aria-haspopup="dialog">展开全部 <span class="filter-count">${values.length-1} 个标签</span><span aria-hidden="true">›</span></button>`:''}</div></div>`}

function openFilterDialog(key){
const options=filterDialogOptions[key];if(!options)return;
const {label,values}=options;
openModal(`<h2 id="filter-dialog-title">全部${esc(label)}</h2><p class="filter-dialog-hint">选择标签，快速筛选影片</p><div class="filter-expanded-body"><div class="filter-all-options" aria-label="全部${esc(label)}">${values.map(([name,value])=>`<button type="button" data-filter="${key}" data-value="${esc(value)}" aria-pressed="${listState[key]===value}" class="${listState[key]===value?'selected':''}">${esc(name)}</button>`).join('')}</div><p class="filter-no-match" hidden>没有匹配的标签，请换个关键词</p></div>`);
$('#modal').classList.add('filter-tags-modal');$('#modal').setAttribute('aria-labelledby','filter-dialog-title');
}

function searchDemoMovie(m,i){return {...m,id:m.id+'demo'+i,slug:'search-demo',name:m.name+' · 演示'+String(i).padStart(2,'0')}}
function renderListing(){const s=listState,isSearch=location.pathname==='/search',pageSize=isSearch?Math.max(36,movies.length):32;const matches=isSearch&&s.q?movies.filter(m=>[m.name,m.actor,m.director].some(v=>v?.toLowerCase().includes(s.q.toLowerCase()))):[];const demos=matches.length&&matches.length<36?Array.from({length:36-matches.length},(_,i)=>searchDemoMovie(matches[i%matches.length],i+1)):[];let result=movies.concat(demos).filter(m=>(!s.cat||catIds[m.category]===s.cat)&&(!s.q||[m.name,m.actor,m.director].some(v=>v?.toLowerCase().includes(s.q.toLowerCase())))&&(!s.tag||m.tags?.some(t=>t.name===s.tag))&&(!s.area||m.area===s.area)&&(!s.language||m.language===s.language)&&(!s.status||(s.status==='全集'?m.duration.startsWith('全'):m.duration.startsWith('更新')))&&(!s.year||(s.year==='更早'?+(m.issue_year||m.issue_date?.slice(0,4))<2025:(m.issue_year||m.issue_date?.slice(0,4))===s.year)));
if(s.sort==='评分高低')result.sort((a,b)=>+b.score-+a.score);else if(s.sort==='人气高低')result.sort((a,b)=>parseFloat(b.heat||0)-parseFloat(a.heat||0));else if(s.sort==='上映时间')result.sort((a,b)=>(b.issue_date||'').localeCompare(a.issue_date||''));
const theme=catalog.themes.find(t=>location.pathname.endsWith(t.id));let title=s.q?`“${esc(s.q)}”的搜索结果`:theme?esc(theme.name):Object.keys(catIds).find(c=>catIds[c]===s.cat)||'全部影片';if(theme){const n=catalog.themes.indexOf(theme);result=movies.filter(m=>n===2?m.category==='短剧':n===3?m.category==='动漫':n===6?/悬疑|惊悚|犯罪/.test(m.tags?.map(t=>t.name).join('')):m.category==='连续剧');}
const tags=[...new Set(movies.filter(m=>!s.cat||catIds[m.category]===s.cat).flatMap(m=>m.tags?.map(t=>t.name)||[]))];const pages=Math.max(1,Math.ceil(result.length/pageSize));s.page=Math.min(s.page,pages);
$('#app').innerHTML=`${location.pathname==='/movie/list'?'<header class="theme-detail-heading"><a href="/" aria-label="返回首页"><img class="page-back-icon" src="/assets/page-back.svg" width="24" height="24" alt=""></a><span>全部分类</span></header>':''}<div class="page listing-page ${isSearch?'search-results-page':''}"><h1 class="${s.q?'':'sr-only'}">${title}</h1>${theme?'':`<div class="list-top"><div class="filter-panel">${filterRow('分类','cat',Object.entries(catIds).map(([label,value])=>[value?label:'全部',value]))}${filterRow('状态','status',[['全部',''],['全集','全集'],['连载','连载']])}${filterRow('类型','tag',[['全部',''],...tags.map(t=>[t,t])])}</div></div>`}<div class="results-bar"><div class="sort-options">${['','上映时间','人气高低','评分高低'].map(x=>`<button class="${s.sort===x?'selected':''}" data-filter="sort" data-value="${x}">${x||'全部'}</button>`).join('')}</div></div>${demos.length?'<p class="search-demo-note">含演示数据，用于预览筛选与分页效果</p>':''}<div class="movie-grid">${listingCards(result.slice((s.page-1)*pageSize,s.page*pageSize),!isSearch&&!theme)||(location.pathname==='/search'?'<div class="rank-empty search-empty" role="status"><img src="/assets/search-empty.png" alt=""><p>阿偶，没有找到您想要的内容哦~</p><button class="primary" data-action="reset-filters">清除筛选</button></div>':'<div class="rank-empty category-empty" role="status"><img src="/assets/category-empty.png" alt=""><p>阿偶，没有找到您想要的内容哦~</p><button class="primary" data-action="reset-filters">清除筛选</button></div>')}</div>${!isSearch&&pages>1?`<nav class="pagination" aria-label="分页">${isSearch?`<span class="rank-page-summary">共 ${result.length} 条 · 每页 ${pageSize} 条</span>`:''}<button data-page="${s.page-1}" ${s.page===1?'disabled':''}>上一页</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${s.page===i+1?'selected':''}">${i+1}</button>`).join('')}<button data-page="${s.page+1}" ${s.page===pages?'disabled':''}>下一页</button></nav>`:''}</div>`;if(s.q&&$('[name=q]'))$('[name=q]').value=s.q;document.title=title.replace(/&[^;]+;/g,'')+' - 万象';}
function episodeCount(m){return m.id==='33f5fd0e81a046a0'?32:+(m.duration.match(/\d+/)?.[0]||1)}
function recommendedMovies(movie,limit=24){
const tags=new Set((movie.tags||[]).map(t=>t.name)),seen=new Set([movie.id]);
return movies.filter(item=>{if(seen.has(item.id)||item.name===movie.name)return false;seen.add(item.id);return true}).map((item,index)=>({item,index,weight:(item.category===movie.category?100:0)+(item.tags||[]).filter(t=>tags.has(t.name)).length*10})).sort((a,b)=>b.weight-a.weight||Number(b.item.score||0)-Number(a.item.score||0)||a.index-b.index).slice(0,limit).map(entry=>entry.item);
}
function detail(path){const id=path.split('-').pop();const base=movies.find(m=>id.startsWith(m.id+'demo'));const m=movies.find(m=>m.id===id)||(base?searchDemoMovie(base,Number(id.slice((base.id+'demo').length))):null);if(!m){$('#app').innerHTML='<div class="empty"><h1>暂未收录这部影片</h1><p>可返回片库浏览已收录影片。</p><a class="primary" href="/movie/list">浏览片库</a></div>';return}currentMovie=m;episode=Math.max(1,+(new URLSearchParams(location.search).get('episode')||1));const hist=read('history').filter(x=>x.id!==m.id);hist.unshift({id:m.id,episode,date:new Date().toISOString()});save('history',hist.slice(0,80));document.title=m.name+' - 万象';const count=episodeCount(m);$('#app').innerHTML=`<div class="page detail-page"><div class="detail-layout"><div class="detail-main"><div class="playback-panel"><div class="player" id="player"><img class="player-poster" src="${m.img}" alt=""><div class="player-title"><a aria-label="返回首页" href="/"><img class="page-back-icon" src="/assets/page-back.svg" width="24" height="24" alt=""></a><img src="${catalog.logo}" alt="万象出品"></div><div class="player-message"></div>${playerControls()}</div><div class="action-bar">${likeButton(m)}${favoriteButton(m)}<button data-action="share"><span class="share-icon" aria-hidden="true"></span><span>分享</span></button><button data-action="线路" aria-expanded="false" aria-controls="line-dropdown"><span class="line-icon" aria-hidden="true"></span><span class="line-label">线路 ${selectedLine}</span></button><button data-action="feedback"><span class="feedback-icon" aria-hidden="true"></span><span>反馈</span></button></div></div><section class="detail-info" id="detail-summary"><h1>${esc(m.name)}</h1><p class="detail-meta">${contentTags(m)}　 |　热度 ${esc(m.heat||'暂无数据')}　 |　${esc(m.score)} 分</p><div class="detail-about"><p class="detail-about-heading">剧情与演职员</p><div class="detail-description"><img src="${m.img}" alt="${esc(m.name)}"><div><p><b>上映：</b>${esc(m.issue_date||m.issue_year||'暂无数据')}</p><p><b>导演：</b>${esc(m.director||'暂无数据')}</p><p class="detail-cast"><b>主演：</b>${esc(m.actor||'暂无数据')}</p><p class="description"><b>简介：</b>${esc(m.description||'当前暂无简介')}</p><button data-action="expand-description">展开简介⌄</button></div></div></div></section><section class="episodes" id="episodes"><div class="episodes-head"><h2>选集</h2><button class="all-episodes-button" data-action="all-episodes" aria-haspopup="dialog">共${count}集 <span aria-hidden="true">›</span></button></div><div class="episode-grid" id="episode-grid">${Array.from({length:count},(_,i)=>`<button class="${i+1===episode?'selected':''}" data-episode="${i+1}">第${i+1}集</button>`).join('')}</div></section><div class="detail-inline-ad">${homeAdRow(0)}</div><section class="catalog-section" id="detail-recommendations"><div class="section-title"><h2>猜你喜欢</h2></div><div class="movie-grid">${recommendedMovies(m).map(card).join('')}</div></section></div></div></div>`;initHomeAds();startHomeAds();}
let rankState={cat:'电影',period:'year',page:1};
function periodHeat(m,period){const raw=String(m.heat||'0'),base=(parseFloat(raw)||0)*(/[w万]/i.test(raw)?10000:1);let hash=0;for(const c of String(m.id))hash=(hash*31+c.charCodeAt(0))>>>0;const month=base*(.06+(hash%120)/1000);return Math.round(period==='year'?base:period==='month'?month:month*(.08+(hash%240)/1000))}
function rank(cat=rankState.cat,period=rankState.period,page=1){const result=(new URLSearchParams(location.search).get('preview')==='empty'?[]:movies).filter(m=>m.category===cat).sort((a,b)=>periodHeat(b,period)-periodHeat(a,period));const pages=Math.max(1,Math.ceil(result.length/30));page=Math.max(1,Math.min(pages,Math.floor(Number(page))||1));rankState={cat,period,page};const offset=(page-1)*30,rows=result.slice(offset,offset+30);$('#app').innerHTML=`<section class="rank-banner" aria-labelledby="rank-heading"><img src="/assets/rank-cinema-banner.png" width="2172" height="330" alt="" fetchpriority="high"><div class="rank-banner-inner"><span class="rank-eyebrow">万象 · 热播精选</span><h1 id="rank-heading">热播排行榜</h1><p class="rank-banner-description">发现热门佳作，追踪人气趋势</p></div></section><div class="page rank-page"><div class="rank-filters"><div class="rank-tabs" role="group" aria-label="影片分类">${['电影','连续剧','综艺','短剧','动漫'].map(c=>`<button data-rank="${c}" aria-pressed="${cat===c}" class="${cat===c?'selected':''}">${c}</button>`).join('')}</div><div class="rank-periods" role="group" aria-label="排行周期">${[['year','年榜'],['month','月榜'],['week','周榜']].map(([value,label])=>`<button type="button" data-rank-period="${value}" aria-pressed="${period===value}" class="${period===value?'selected':''}">${label}</button>`).join('')}</div></div><div class="rank-grid">${rows.map((m,i)=>`<a href="${movieUrl(m)}" class="rank-item"><div class="rank-poster"><span class="rank-number">${offset+i+1}</span><img src="${m.img}" alt="${esc(m.name)}" loading="lazy"></div><div class="rank-info"><div class="rank-title-row"><h3>${esc(m.name)}</h3><span class="rank-rating">${esc(m.score)}<small> 分</small></span></div><p class="rank-metadata">${esc([m.category,m.issue_year||m.issue_date?.slice(0,4),m.actor?.split(/[,，、/]/).slice(0,2).join(' / ')].filter(Boolean).join(' · '))}</p><div class="rank-content-tags">${contentTags(m)}</div><p class="rank-heat">${{year:'年',month:'月',week:'周'}[period]}热度 ${periodHeat(m,period).toLocaleString('zh-CN')}</p></div></a>`).join('')||'<div class="rank-empty" role="status"><img src="/assets/rank-empty.png" width="1536" height="1024" alt=""><p>阿偶，没有找到您想要的内容哦~</p></div>'}</div>${result.length?`<nav class="pagination rank-pagination" aria-label="排行榜分页"><span class="rank-page-summary">共 ${result.length} 条 · 每页 30 条</span><button type="button" data-rank-page="${page-1}" ${page===1?'disabled':''}>上一页</button>${Array.from({length:pages},(_,i)=>`<button type="button" data-rank-page="${i+1}" class="${page===i+1?'selected':''}" ${page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button type="button" data-rank-page="${page+1}" ${page===pages?'disabled':''}>下一页</button></nav>`:''}</div>`}
function mine(path){if(path==='/mine/invitations'){invitationRecordsPage();return}if(path==='/mine/share'){promotionPage();return}if(path==='/mine/settings/recovery'){accountRecoveryPage();return}if(path==='/mine/settings/password'){accountPasswordPage();return}if(path==='/mine/settings'){settingsPage();return}if(path==='/mine/invite'){invitePage();return}if(path==='/mine/help'){$('#app').innerHTML=`<div class="page help"><h1>帮助中心</h1>${[['如何寻找影片？','通过顶部搜索框输入片名或演员，在分类页按类型、地区、年份筛选，也可以浏览排行榜。'],['为什么影片无法播放？','当前页面是界面复刻，尚未接入可用的授权播放源。播放器支持选择本机视频进行播放，视频不会上传。'],['收藏和观看记录保存在哪里？','收藏和浏览记录仅保存在当前浏览器中，清除浏览器数据后会消失。'],['可以使用原站账号登录吗？','不能。此页面没有连接原站账号服务，不会提交或保存你输入的账号密码。'],['隐私与反馈','本页面的搜索、收藏与观看记录仅在本机处理。反馈功能展示表单，但不会向原站发送信息。']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;return}const history=path==='/mine/history';const ids=history?read('history').map(x=>x.id):read('favorites');const selected=ids.map(id=>movies.find(m=>m.id===id)).filter(Boolean);$('#app').innerHTML=`<div class="page personal-center"><header class="invite-heading"><a href="/mine" aria-label="返回个人中心"><img class="page-back-icon" src="/assets/page-back.svg" width="24" height="24" alt=""></a><h1>${history?'观看历史':'我的收藏'}</h1></header><section class="personal-content" aria-labelledby="personal-content-title"><div class="personal-content-heading"><h2 id="personal-content-title">${history?'观看记录':'我的收藏'}<span>${selected.length} 部</span></h2></div><div class="movie-grid">${selected.map(card).join('')||(history?'<div class="empty"><h2>暂无观看记录</h2><p>浏览影片详情后会在这里显示。</p><a class="primary" href="/">去发现影片</a></div>':'<div class="rank-empty favorites-empty" role="status"><img src="/assets/favorites-empty.png" alt=""><p>阿偶，没有找到您想要的内容哦~</p></div>')}</div></section></div>`}
