const actions={'all-episodes':showAllEpisodes,'mobile-search':()=>navigate('/search'),线路:showLineMenu,top:()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'}),login,close:()=>$('#modal').close(),vip:()=>openModal('<h2>VIP 会员</h2><p class="muted">该功能暂未开发</p>'),history:()=>setHistoryOpen(true),favorite:addMovieFavorite,like:addMovieLike,dislike:()=>{const b=$('[data-action=dislike]');b.classList.toggle('active');$('[data-action=like]').classList.remove('active')},share:showShareCard,'copy-share':copyShareLink,feedback:showFeedback,play,episodes:()=>$('#episodes').scrollIntoView({behavior:'smooth'}),'prev-episode':()=>setEpisode(episode-1),'next-episode':()=>setEpisode(episode+1),fullscreen:()=>$('#player').requestFullscreen?.().catch(()=>toast('当前环境不支持全屏')),'expand-description':()=>{const p=$('.description');p.classList.toggle('expanded');$('[data-action=expand-description]').textContent=p.classList.contains('expanded')?'收起简介⌃':'展开简介⌄'},'toggle-episodes':()=>{const g=$('.episode-grid'),b=$('[data-action=toggle-episodes]');const expanded=g.classList.toggle('expanded');b.setAttribute('aria-expanded',String(expanded));b.textContent=expanded?'收起选集 ⌃':'展开全部 ⌄'},'reverse-episodes':()=>{const g=$('.episode-grid');[...g.children].reverse().forEach(e=>g.append(e))},'reset-filters':()=>{const query=listState.q;listState={cat:'',tag:'',area:'',language:'',year:'',status:'',sort:'',q:query,page:1};updateFilter()},'clear-history':()=>{save('history',[]);mine('/mine/history');toast('观看记录已清空')}};
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.getAttribute('href')?.startsWith('/')&&!e.ctrlKey&&!e.metaKey){e.preventDefault();navigate(a.getAttribute('href'));return}const b=e.target.closest('button');if(!b)return;if(b.dataset.openFilter){openFilterDialog(b.dataset.openFilter);return}if(b.dataset.action){actions[b.dataset.action]?.();return}if(b.dataset.fav){const f=read('favorites'),id=b.dataset.fav,has=f.includes(id);save('favorites',has?f.filter(x=>x!==id):[...f,id]);b.textContent=has?'☆ 收藏':'★ 已收藏';toast(has?'已取消收藏':'已加入我的收藏');return}if(b.dataset.slide!==undefined){slide(+b.dataset.slide);clearInterval(heroTimer)}if(b.dataset.heroStep){clearInterval(heroTimer);slide(heroIndex+ +b.dataset.heroStep)}if(b.dataset.row){const row=$('#row-'+b.dataset.row);row.scrollBy({left:row.clientWidth*+b.dataset.step,behavior:'smooth'})}if(b.dataset.filter){if(b.closest('.filter-tags-modal'))$('#modal').close();listState[b.dataset.filter]=b.dataset.value;listState.page=1;updateFilter()}if(b.dataset.page){listState.page=+b.dataset.page;updateFilter();window.scrollTo({top:250,behavior:'smooth'})}if(b.dataset.rank)rank(b.dataset.rank);if(b.dataset.rankPeriod)rank(rankState.cat,b.dataset.rankPeriod);if(b.dataset.rankPage){rank(rankState.cat,rankState.period,+b.dataset.rankPage);$('.rank-filters').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})}if(b.dataset.episode)setEpisode(+b.dataset.episode)});
document.addEventListener('keydown',e=>{if(!e.target.closest('.hero-thumbs')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();clearInterval(heroTimer);slide(e.key==='Home'?0:e.key==='End'?catalog.banners.length-1:heroIndex+(e.key==='ArrowRight'?1:-1));document.querySelector(`[data-slide="${heroIndex}"]`)?.focus({preventScroll:true})});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.matches('.search-form')){const q=new FormData(e.target).get('q').trim();if(q){e.target.querySelector('input').blur();$('#modal').close();navigate('/search?q='+encodeURIComponent(q))}else toast('请输入片名或演员')}if(e.target.id==='login-form'){submitAuthDemo(e.target)}if(e.target.id==='feedback-form'){submitFeedback(e.target)}});
document.addEventListener('change',e=>{if(e.target.id==='local-video'&&e.target.files[0]){if(localVideo)URL.revokeObjectURL(localVideo);localVideo=URL.createObjectURL(e.target.files[0]);attachVideo($('#player'),localVideo,toast)}if(e.target.id==='speed'&&$('video'))$('video').playbackRate=+e.target.value});
window.addEventListener('popstate',route);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
try{const response=await fetch('/catalog.json');if(!response.ok)throw Error('catalog');catalog=await response.json();const all=catalog.home_recommends.flatMap(s=>s.items).concat(catalog.sections.flatMap(s=>s.items),catalog.extraMovies||[]);const map=new Map();for(const m of all){m.duration=m.duration||'暂无集数';m.tags=m.tags||[];m.category=typeof m.category==='object'?m.category.name:m.category;if(!map.has(m.name))map.set(m.name,m)}movies=[...map.values()];for(const b of catalog.banners){const m=movies.find(m=>m.name===b.name||m.name.replace('来','來')===b.name);if(m&&b.link.startsWith('/movie/detail/')){const full=b.link.split('/').pop();m.id=full.split('-').pop();m.slug=full.slice(0,full.lastIndexOf('-'))}}seedHistoryDemo();route()}catch(e){window.clearPageSkeleton?.();$('#app').innerHTML='<div class="empty"><h1>影片资料加载失败</h1><p>请检查网络后刷新页面。</p><button class="primary" onclick="location.reload()">重新加载</button></div>';console.error(e)}

function themePage(path){const t=catalog.themeDetails?.find(t=>path.endsWith(t.id));if(!t){listing();return}document.title=t.name+' - 万象';$('#app').innerHTML=`<header class="theme-detail-heading"><a href="/" aria-label="返回首页"><img class="page-back-icon" src="/assets/page-back.svg" width="24" height="24" alt="">返回</a><span>专题详情</span></header><section class="theme-hero" aria-labelledby="theme-title"><img src="${t.bg_img}" alt=""><div class="theme-hero-copy"><h1 id="theme-title">${esc(t.name)}</h1><p class="theme-description">${esc(t.description)}</p></div></section><div class="page">${themeAllContent(t)}</div>`}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();document.modelContext.registerTool({name:'search_films',title:'搜索影片',description:'在当前片库中搜索片名或演员，打开搜索结果页面。',inputSchema:{type:'object',properties:{query:{type:'string',minLength:1}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||!input.query.trim())throw new Error('请输入搜索词');const query=input.query.trim();navigate('/search?q='+encodeURIComponent(query));return {query,results:movies.filter(m=>[m.name,m.actor,m.director].some(v=>v?.includes(query))).map(m=>({id:m.id,name:m.name})).slice(0,30)}}},{signal:lifecycle.signal});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}

function positionHoverPreview(e){const card=e.target.closest?.(':is(.movie-grid,.feature-track) .movie-card');if(!card||card.contains(e.relatedTarget))return;const rect=card.getBoundingClientRect(),width=Math.min(288,Math.max(240,rect.width+48)),left=rect.left+(rect.width-width)/2;const bounded=Math.max(12,Math.min(left,window.innerWidth-width-12));card.style.setProperty('--hover-offset',(bounded-left)+'px');card.style.setProperty('--preview-left',(rect.left+rect.width/2)+'px');card.style.setProperty('--preview-top',(rect.top-10)+'px');card.style.setProperty('--preview-width',width+'px')}
document.addEventListener('pointerover',positionHoverPreview);
document.addEventListener('focusin',positionHoverPreview);

// Keep fixed carousel previews anchored during page and carousel scrolling.
document.addEventListener('scroll',()=>{document.querySelectorAll('.feature-track .movie-card:is(:hover,:focus-within)').forEach(card=>positionHoverPreview({target:card,relatedTarget:null}))},true);
window.addEventListener('resize',()=>{document.querySelectorAll('.feature-track .movie-card:is(:hover,:focus-within)').forEach(card=>positionHoverPreview({target:card,relatedTarget:null}))});

function seedHistoryDemo(){
 if(localStorage.getItem('sa-history-demo-seeded'))return;
 const existing=read('history');
 const demo=movies.filter(m=>!existing.some(x=>x.id===m.id)).slice(0,8).map((m,i)=>({id:m.id,episode:Math.min(i+1,+(m.duration.match(/\d+/)?.[0]||1)),date:new Date(Date.now()-i*3600000).toISOString(),demo:true}));
 save('history',[...existing,...demo].slice(0,80));
 localStorage.setItem('sa-history-demo-seeded','1');
}
function renderHistoryDrawer(){
 const panel=$('#history-drawer');if(!panel)return;
 const entries=read('history').map(h=>({h,m:movies.find(m=>m.id===h.id)})).filter(x=>x.m);
 panel.innerHTML=`<div class="history-drawer-head"><h3>最近观看</h3><span>${entries.length} 条记录</span></div>${entries.length?`<div class="history-scroll" tabindex="0" aria-label="观看记录，可上下滚动">${entries.map(({h,m})=>`<a class="history-entry" href="${movieUrl(m)}?episode=${Math.max(1,+h.episode||1)}"><img src="${m.img}" alt=""><span class="history-entry-copy"><span class="history-entry-title">${esc(m.name)}</span><span class="history-entry-meta">看到第 ${Math.max(1,+h.episode||1)} 集${h.demo?' · 模拟记录':''}</span></span><span class="history-entry-play">继续看 ›</span></a>`).join('')}</div>`:'<p class="history-drawer-empty">暂无观看记录，去发现喜欢的影片吧</p>'}<a class="history-drawer-footer" href="/mine/history">查看全部观看记录 ›</a>`;
}
function setHistoryOpen(open){const button=$('.history-menu .history'),panel=$('#history-drawer');if(!button||!panel)return;if(open&&panel.hidden)renderHistoryDrawer();panel.hidden=!open;button.setAttribute('aria-expanded',String(open));}
document.addEventListener('pointerover',e=>{const menu=e.target.closest?.('.history-menu');if(menu&&!menu.contains(e.relatedTarget))setHistoryOpen(true)});
document.addEventListener('pointerout',e=>{const menu=e.target.closest?.('.history-menu');if(menu&&!menu.contains(e.relatedTarget)&&!menu.contains(document.activeElement))setHistoryOpen(false)});
document.addEventListener('focusin',e=>{if(e.target.closest?.('.history-menu'))setHistoryOpen(true)});
document.addEventListener('focusout',e=>{const menu=e.target.closest?.('.history-menu');if(menu&&!menu.contains(e.relatedTarget))setHistoryOpen(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')setHistoryOpen(false)});
document.addEventListener('click',e=>{if(!e.target.closest?.('.history-menu'))setHistoryOpen(false)});

function playerControls(){return `<div class="transport"><div class="jump-row"><div class="jump-group"><button data-seek="-900" aria-label="后退15分钟">≪ 15m</button><button data-seek="-15" aria-label="后退15秒">‹ 15S</button></div><div class="jump-group"><button data-seek="15" aria-label="前进15秒">15S ›</button><button data-seek="900" aria-label="前进15分钟">15m ≫</button></div></div><div class="transport-row"><button class="round" data-seek="-15" aria-label="后退15秒">${transportIcon("back")}</button><button class="round" data-action="play" aria-label="播放" data-transport-play>${transportIcon("play")}</button><button class="round" data-seek="15" aria-label="前进15秒">${transportIcon("forward")}</button><input class="seek-range" type="range" min="0" max="100" value="0" step="0.1" aria-label="播放进度" disabled><span class="remaining">−00:00</span><div class="volume-control"><div class="volume-popover" id="volume-popover" hidden><output class="volume-value">50</output><input class="volume-range" type="range" min="0" max="100" value="50" step="1" aria-label="音量" aria-valuetext="50%" style="--volume:50%"></div><button class="round" data-volume-toggle aria-label="调整音量" aria-expanded="false" aria-controls="volume-popover">${transportIcon("volume")}</button></div><div class="player-settings"><button class="round" data-player-settings aria-label="播放设置" aria-expanded="false" aria-controls="speed-dropdown"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m9 3 1-1h4l1 3 3 2 3 1v4l-2 2-1 3-3 1-1 3h-4l-1-3-3-2-3-1v-4l2-2 1-3z"/><circle cx="12" cy="12" r="3"/></svg></button><div class="player-settings-panel" id="player-settings-panel" hidden><label>播放速度<select class="transport-speed" aria-label="播放速度"><option value="0.75">0.75X</option><option value="1" selected>1.0X</option><option value="1.5">1.5X</option></select></label></div></div><button class="round" data-player-fullscreen aria-label="全屏">${transportIcon("full")}</button></div></div>`}
const format=s=>{s=Math.max(0,Math.floor(s||0));const h=Math.floor(s/3600),m=Math.floor(s%3600/60);return (h?h+':':'')+String(m).padStart(2,'0')+':'+String(s%60).padStart(2,'0')};
function attachVideo(player,url,toast){
 player.querySelector('video')?.remove();player.querySelector('.player-message').hidden=true;
 const video=document.createElement('video');video.className='video-source';video.playsInline=true;video.src=url;player.prepend(video);
 const sync=()=>{const range=player.querySelector('.seek-range'),valid=Number.isFinite(video.duration)&&video.duration>0;range.disabled=!valid;range.max=valid?video.duration:100;range.value=video.currentTime;range.style.setProperty('--progress',valid?100*video.currentTime/video.duration+'%':'0%');range.setAttribute('aria-valuetext',format(video.currentTime)+' / '+format(video.duration));player.querySelector('.remaining').textContent='−'+format(valid?video.duration-video.currentTime:0);const play=player.querySelector('[data-transport-play]');play.innerHTML=transportIcon(video.paused?'play':'pause');play.setAttribute('aria-label',video.paused?'播放':'暂停');updateVolumeUI(player,video.muted?0:Math.round(video.volume*100));};
 for(const event of ['loadedmetadata','durationchange','timeupdate','play','pause','ended','volumechange'])video.addEventListener(event,sync);
 video.volume=+player.querySelector('.volume-range').value/100;video.playbackRate=+player.querySelector('.transport-speed').value;video.addEventListener('error',()=>toast('浏览器无法播放此格式，请选择 MP4 或 WebM'));video.play().catch(()=>{});sync();
}
document.addEventListener('click',async e=>{const button=e.target.closest('.transport button');if(!button)return;const player=button.closest('.player'),video=player.querySelector('video');if(button.hasAttribute('data-player-fullscreen')){try{document.fullscreenElement?await document.exitFullscreen():await player.requestFullscreen()}catch{}return}if(!video)return;if(button.dataset.seek){if(Number.isFinite(video.duration))video.currentTime=Math.max(0,Math.min(video.duration,video.currentTime+Number(button.dataset.seek)))}});
document.addEventListener('input',e=>{if(!e.target.matches('.seek-range'))return;const video=e.target.closest('.player').querySelector('video');if(video&&Number.isFinite(video.duration))video.currentTime=+e.target.value;});
document.addEventListener('change',e=>{if(!e.target.matches('.transport-speed'))return;const video=e.target.closest('.player').querySelector('video');if(video)video.playbackRate=+e.target.value;});

function transportIcon(name){const paths={play:'<path d="m8 5 12 7-12 7z" fill="currentColor" stroke="none"/>',pause:'<path d="M8 5v14M16 5v14" stroke-width="4"/>',back:'<path d="m12 6-8 6 8 6zm8 0-8 6 8 6z" fill="currentColor" stroke="none"/>',forward:'<path d="m4 6 8 6-8 6zm8 0 8 6-8 6z" fill="currentColor" stroke="none"/>',volume:'<path d="M4 9h4l5-4v14l-5-4H4z" fill="currentColor"/><path d="M16 8q4 4 0 8m3-11q7 7 0 14"/>',muted:'<path d="M4 9h4l5-4v14l-5-4H4z" fill="currentColor"/><path d="m17 9 5 6m0-6-5 6M3 3l18 18"/>',full:'<path d="M9 4H4v5m11-5h5v5M4 15v5h5m6 0h5v-5M4 4l6 6m10-6-6 6m-4 4-6 6m10-6 6 6"/>'};return '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[name]+'</svg>'}

document.addEventListener("click",e=>{const b=e.target.closest("[data-line]");if(!b)return;selectedLine=Number(b.dataset.line);const label=$(".line-label");if(label)label.textContent="线路 "+selectedLine;closeLineMenu();toast("已选择线路 "+selectedLine+"（模拟线路）")});

function movieLikes(id){const entry=read('like-counts').find(x=>x.id===id);return entry&&Number.isSafeInteger(entry.count)&&entry.count>=0?entry.count:1280}
function likeButton(m){return `<button data-action="like" class="animated-like" aria-label="点赞，当前 ${movieLikes(m.id)} 赞"><span class="heart-mark" aria-hidden="true"><svg class="heart-outline" viewBox="0 0 24 24"><path d="M17.5,1.917a6.4,6.4,0,0,0-5.5,3.3,6.4,6.4,0,0,0-5.5-3.3A6.8,6.8,0,0,0,0,8.967c0,4.547,4.786,9.513,8.8,12.88a4.974,4.974,0,0,0,6.4,0C19.214,18.48,24,13.514,24,8.967A6.8,6.8,0,0,0,17.5,1.917Zm-3.585,18.4a2.973,2.973,0,0,1-3.83,0C4.947,16.006,2,11.87,2,8.967a4.8,4.8,0,0,1,4.5-5.05A4.8,4.8,0,0,1,11,8.967a1,1,0,0,0,2,0,4.8,4.8,0,0,1,4.5-5.05A4.8,4.8,0,0,1,22,8.967C22,11.87,19.053,16.006,13.915,20.313Z"/></svg><svg class="heart-filled" viewBox="0 0 24 24"><path d="M17.5,1.917a6.4,6.4,0,0,0-5.5,3.3,6.4,6.4,0,0,0-5.5-3.3A6.8,6.8,0,0,0,0,8.967c0,4.547,4.786,9.513,8.8,12.88a4.974,4.974,0,0,0,6.4,0C19.214,18.48,24,13.514,24,8.967A6.8,6.8,0,0,0,17.5,1.917Z"/></svg><svg class="heart-celebrate" viewBox="0 0 100 100"><path d="m10 10 10 10M10 50h10m0 30 10-10m60-60-10 10m10 30H80m0 30L70 70"/></svg></span><span class="action-label-count">赞 <span class="like-count" aria-live="polite" aria-atomic="true">${movieLikes(m.id).toLocaleString('en-US')}</span></span><span class="like-plus" aria-hidden="true">+1</span></button>`}
function addMovieLike(){if(!currentMovie)return;const id=currentMovie.id,count=movieLikes(id)+1;save('like-counts',[...read('like-counts').filter(x=>x.id!==id),{id,count}]);const b=$('[data-action=like]');b.classList.add('active');$('[data-action=dislike]')?.classList.remove('active');b.querySelector('.like-count').textContent=count.toLocaleString('en-US');b.setAttribute('aria-label','点赞，当前 '+count+' 赞');b.classList.remove('celebrating');void b.offsetWidth;b.classList.add('celebrating')}

function favoriteCount(id){const entry=read('favorite-counts').find(x=>x.id===id);return entry&&Number.isSafeInteger(entry.count)&&entry.count>=0?entry.count:368}
function favoriteButton(m){const saved=read('favorites').includes(m.id);return `<button data-action="favorite" class="animated-favorite ${saved?'active':''}" aria-label="收藏，当前 ${favoriteCount(m.id)} 次"><svg class="bookmark-icon" viewBox="0 0 24 24" aria-hidden="true"><path class="bookmark-back" d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/><path class="bookmark-check" d="M8 11l3 3 5-5"/></svg><span class="action-label-count"><span class="favorite-label">${saved?'已收藏':'收藏'}</span><span class="favorite-count" aria-live="polite" aria-atomic="true">${favoriteCount(m.id).toLocaleString('en-US')}</span></span><span class="favorite-plus" aria-hidden="true">+1</span></button>`}
function addMovieFavorite(){if(!currentMovie)return;const id=currentMovie.id,favorites=read('favorites'),saved=favorites.includes(id),count=Math.max(0,favoriteCount(id)+(saved?-1:1));save('favorites',saved?favorites.filter(x=>x!==id):[...favorites,id]);save('favorite-counts',[...read('favorite-counts').filter(x=>x.id!==id),{id,count}]);const b=$('[data-action=favorite]');b.classList.toggle('active',!saved);b.querySelector('.favorite-label').textContent=saved?'收藏':'已收藏';b.querySelector('.favorite-count').textContent=count.toLocaleString('en-US');b.querySelector('.favorite-plus').textContent=saved?'−1':'+1';b.setAttribute('aria-label',(saved?'收藏':'取消收藏')+'，当前 '+count+' 次');b.classList.remove('celebrating');void b.offsetWidth;b.classList.add('celebrating');toast(saved?'已取消收藏':'已加入我的收藏')}

function showShareCard(){if(!currentMovie)return;const m=currentMovie,text=`我正在万象看《${m.name}》，快来和我一起看吧！`,url=location.href;const links={facebook:'https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(url),x:'https://twitter.com/intent/tweet?text='+encodeURIComponent(text)+'&url='+encodeURIComponent(url),telegram:'https://t.me/share/url?url='+encodeURIComponent(url)+'&text='+encodeURIComponent(text)};openModal(`<section class="share-card" aria-label="分享影片"><div class="share-summary"><img class="share-poster" src="${esc(m.img)}" alt="${esc(m.name)}"><div class="share-copy"><h2>${esc(m.name)}</h2><p class="share-stats">${contentTags(m)}<strong>🔥 ${esc(m.heat||'暂无热度')}</strong><strong>${esc(m.score)} <small>分</small></strong></p><p class="share-message">${esc(text)}</p></div></div><div class="share-platforms"><a class="share-platform facebook" href="${esc(links.facebook)}" target="_blank" rel="noopener noreferrer" aria-label="分享到 Facebook" title="分享到 Facebook"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M14 22v-9h3l.5-4H14V7c0-1 .3-2 2-2h2V1.5A24 24 0 0 0 15 1c-3 0-5 2-5 5v3H7v4h3v9z"/></svg></a><a class="share-platform x" href="${esc(links.x)}" target="_blank" rel="noopener noreferrer" aria-label="分享到 X" title="分享到 X"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3h5l13 18h-5zM21 3 3 21" fill="none" stroke="currentColor" stroke-width="1.8"/></svg></a><a class="share-platform telegram" href="${esc(links.telegram)}" target="_blank" rel="noopener noreferrer" aria-label="分享到 Telegram" title="分享到 Telegram"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M21 3 2 10c-1 .4-1 .9 0 1.2l5 1.6 2 6c.2.6.5.6.8.3l3-3 5 3.7c.8.5 1.3.2 1.5-.7L22 4c.2-1-.2-1.3-1-1zM8 12l10-6-8 8-.5 3z"/></svg></a><button class="share-platform copy-link" data-action="copy-share" aria-label="复制分享链接" title="复制链接"><svg viewBox="0 0 24 24" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="m10 8 3-3a4 4 0 0 1 6 6l-3 3M14 16l-3 3a4 4 0 0 1-6-6l3-3M8 16l8-8"/></g></svg></button></div><div class="share-link-fallback" hidden><label>分享链接<input readonly aria-label="分享链接" value="${esc(url)}"></label><p>请复制上方链接</p></div></section>`)}
async function copyShareLink(){try{await navigator.clipboard.writeText(location.href);toast('链接已复制')}catch{const box=$('.share-link-fallback');if(box){box.hidden=false;box.querySelector('input').select()}}}

function showFeedback(){const issues=[['视频卡顿','播放过程中频繁停顿','M19 7a8 8 0 1 0 1 7M19 3v4h-4'],['无法播放','视频无法正常启动','M3 3l18 18M4 7v10h12V7H4m12 3 5-3v10l-5-3'],['音画不同步','声音与画面存在延迟','M3 10v4m4-8v12m5-15v18m5-15v12m4-8v4'],['视频闪退','播放时突然退出或崩溃','m13 2-9 12h7l-1 8 10-13h-7z'],['黑屏','画面全黑但音频正常','M3 4h18v13H3zM12 17v4m-5 0h10'],['其他问题','描述你遇到的其他问题','M3 4h18v13H8l-5 4z']];openModal(`<section class="feedback-panel"><header><span class="feedback-dot"></span>用户反馈</header><h2 id="feedback-heading">遇到了什么问题？</h2><p class="feedback-intro">选择问题即可提交，其他问题可补充说明。</p><form id="feedback-form"><fieldset class="feedback-options"><legend class="sr-only">问题类型</legend>${issues.map(([name,desc,path])=>`<label class="feedback-choice"><input type="radio" name="issue" value="${name}" required><span class="feedback-choice-body"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg><strong>${name}</strong><small>${desc}</small></span></label>`).join('')}</fieldset><div class="feedback-description" hidden><textarea name="feedback" maxlength="100" rows="5" aria-label="补充问题描述" placeholder="请描述遇到的问题"></textarea><span class="feedback-counter"><span id="feedback-count">0</span>/100</span></div><p class="feedback-local-note">反馈暂存于当前浏览器，尚未接入客服服务。</p><button type="submit" class="primary feedback-submit" hidden disabled>提交反馈</button><p class="feedback-result" role="status" hidden></p></form></section>`);$('#modal').classList.add('feedback-sheet');$('#modal').setAttribute('aria-labelledby','feedback-heading')}
function submitFeedback(form){const data=new FormData(form),issue=data.get('issue'),description=issue==='其他问题'?String(data.get('feedback')||'').trim():'';if(!issue){form.reportValidity();return}if(issue==='其他问题'&&!description){const input=form.querySelector('textarea');input.setCustomValidity('请补充你遇到的问题');input.reportValidity();return}const records=read('feedback-records');save('feedback-records',[{movieId:currentMovie?.id,issue,description,line:selectedLine,episode,date:new Date().toISOString()},...records].slice(0,50));$('#modal').close();toast('已提交，感谢您的反馈');const node=$('#toast');node.classList.add('feedback-success');node.innerHTML='<span class="feedback-success-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="currentColor"/><path d="m7 12 3 3 7-7" fill="none" stroke="#174737" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span>已提交，感谢您的反馈</span>';}
document.addEventListener('input',e=>{if(!e.target.matches('#feedback-form textarea'))return;e.target.setCustomValidity('');$('#feedback-count').textContent=e.target.value.length;e.target.closest('form').querySelector('.feedback-submit').disabled=!e.target.value.trim();});

document.addEventListener('change',e=>{if(e.target.matches('#feedback-form input[name=issue]')){const form=$('#feedback-form'),other=e.target.value==='其他问题';form.querySelector('textarea').setCustomValidity('');form.querySelector('.feedback-description').hidden=!other;form.querySelector('.feedback-submit').hidden=!other;form.querySelector('.feedback-submit').disabled=!form.querySelector('textarea').value.trim();if(other)form.querySelector('textarea').focus();else submitFeedback(form)}});

function updateVolumeUI(player,value){const range=player.querySelector('.volume-range');range.value=value;range.style.setProperty('--volume',value+'%');range.setAttribute('aria-valuetext',value+'%');player.querySelector('.volume-value').textContent=value;player.querySelector('[data-volume-toggle]').innerHTML=transportIcon(value===0?'muted':'volume')}
function closeVolume(){const panel=$('.volume-popover');if(panel){panel.hidden=true;$('[data-volume-toggle]').setAttribute('aria-expanded','false')}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-volume-toggle]');if(button){const panel=button.closest('.volume-control').querySelector('.volume-popover');panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden));return}if(!e.target.closest('.volume-control'))closeVolume()});
document.addEventListener('input',e=>{if(!e.target.matches('.volume-range'))return;const player=e.target.closest('.player'),value=Number(e.target.value),video=player.querySelector('video');updateVolumeUI(player,value);if(video){video.volume=value/100;video.muted=value===0}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&e.target.closest('.volume-control')){closeVolume();$('[data-volume-toggle]').focus()}});

document.addEventListener('click',e=>{const button=e.target.closest('[data-close-ad]');if(button)button.closest('.left-ad').remove()});

function submitAuthDemo(form){if(form.dataset.busy==='true')return;syncAuthForm(form);const button=form.querySelector('.auth-submit');if(button.disabled||!form.reportValidity())return;const account=form.querySelector('[name=account]').value.trim(),register=form.dataset.mode==='register';form.dataset.busy='true';button.disabled=true;button.textContent=register?'注册中…':'登录中…';form.querySelectorAll('input').forEach(input=>input.disabled=true);setTimeout(()=>{if(!form.isConnected||!$('#modal').open)return;form.querySelectorAll('input[type=password],input[name=password],input[name=confirm]').forEach(input=>input.value='');if(register){demoRegisteredAccounts.add(account.toLowerCase());login();$('#auth-account').value=account;toast('演示注册成功，请登录')}else{demoAccount=account;$('#modal').close();navigate('/mine');toast('登录成功')}},400)}
document.addEventListener('click',e=>{if(e.target.closest('[data-auth-logout]')){demoAccount='';$('#modal').close();navigate('/');toast('已退出登录')}});

function getSearchHistory(){if(searchHistoryCache)return searchHistoryCache;try{const raw=localStorage.getItem('sa-search-history');const data=raw===null?[]:JSON.parse(raw);searchHistoryCache=Array.isArray(data)?[...new Set(data.filter(x=>typeof x==='string'&&x.trim()))].slice(0,10):[]}catch{searchHistoryCache=[]}return searchHistoryCache}
function persistSearchHistory(items){searchHistoryCache=items;try{save('search-history',items)}catch{}}
function rememberSearch(query){const q=String(query||'').trim();if(q)persistSearchHistory([q,...getSearchHistory().filter(x=>x!==q)].slice(0,10))}
function searchPageHistory(){const items=getSearchHistory();return `<section class="page-search-history" aria-label="历史搜索"><div class="page-history-heading"><h2>历史搜索</h2>${items.length?'<button type="button" data-search-clear aria-label="清空搜索历史">清空</button>':''}</div><div class="page-history-tags">${items.length?items.map((q,i)=>`<div class="page-history-tag"><a href="/search?q=${encodeURIComponent(q)}">${esc(q)}</a><button type="button" data-search-delete="${i}" aria-label="删除搜索记录：${esc(q)}">×</button></div>`).join(''):'<p class="page-history-empty">暂无搜索记录</p>'}</div></section>`}
function searchDrawer(){const items=getSearchHistory();return `<section class="search-history-section" aria-label="历史搜索"><div class="search-drawer-heading"><h3>历史搜索</h3>${items.length?'<button type="button" data-search-clear>清空</button>':''}</div><div class="search-history-list">${items.length?items.map((q,i)=>`<div class="search-history-row"><a href="/search?q=${encodeURIComponent(q)}"><span>${esc(q)}</span></a><button type="button" data-search-delete="${i}" aria-label="删除搜索记录：${esc(q)}">×</button></div>`).join(''):'<p class="search-history-empty">暂无搜索记录</p>'}</div></section><section class="search-popular" aria-label="热门搜索"><h3>热门搜索</h3>${['醒来','交锋','重器','凡人修仙传','哪吒之魔童闹海'].map((q,i)=>`<a href="/search?q=${encodeURIComponent(q)}"><span class="search-rank">${i+1}</span>${esc(q)}</a>`).join('')}</section>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-search-delete],[data-search-clear]');if(!b)return;const items=getSearchHistory();persistSearchHistory(b.hasAttribute('data-search-clear')?[]:items.filter((_,i)=>i!==Number(b.dataset.searchDelete)));const section=b.closest('.page-search-history');if(section){section.outerHTML=searchPageHistory();return}const drawer=b.closest('.search-suggest');if(!drawer)return;drawer.innerHTML=searchDrawer();const next=drawer.querySelector('[data-search-delete]')||drawer.closest('form').querySelector('input');next.focus()});

function trackPosterLoading(){document.querySelectorAll('.poster img').forEach(img=>{if(img.complete||img.dataset.loadingTracked)return;img.dataset.loadingTracked='true';const poster=img.closest('.poster');poster.classList.add('media-loading');const finish=()=>poster.classList.remove('media-loading');img.addEventListener('load',finish,{once:true});img.addEventListener('error',finish,{once:true})})}
if(typeof MutationObserver!=='undefined'){new MutationObserver(trackPosterLoading).observe($('#app'),{childList:true,subtree:true});trackPosterLoading()}

function commercialAds(){return [['audio','无线听觉'],['coffee','日常有咖啡'],['travel','周末去远方'],['sport','轻装出发'],['home','让家更舒适'],['learning','每天学一点']].map(([id,name])=>({id,name,content:adImages[id]}))}
function homeAdRow(index){const source=commercialAds(),ads=Array.from({length:3},(_,i)=>source[(index+i)%source.length]);return `<section class="home-ad-row" aria-label="广告轮播 ${index+1}" aria-roledescription="轮播"><div class="home-ad-track" tabindex="0" aria-label="广告图片，可左右滑动">${ads.map((a,i)=>`<button type="button" class="home-ad-card" data-commercial-ad="${a.id}" aria-label="推广：${a.name}，第 ${i+1} 张"><img src="${a.content}" width="400" height="225" alt="${a.name}" loading="lazy" decoding="async"></button>`).join('')}</div><span class="ad-label">广告</span><div class="ad-controls"><button type="button" data-ad-step="-1" aria-label="上一张广告">‹</button><div class="ad-dots">${ads.map((a,i)=>`<button type="button" data-ad-index="${i}" aria-label="查看第 ${i+1} 张广告" aria-pressed="${i===0}" class="${i===0?'selected':''}"></button>`).join('')}</div><button type="button" data-ad-step="1" aria-label="下一张广告">›</button></div></section>`}
function adSlideWidth(track){const cards=track.querySelectorAll('.home-ad-card');return cards.length>1?cards[1].offsetLeft-cards[0].offsetLeft:track.clientWidth}
function initHomeAds(){document.querySelectorAll('.home-ad-row').forEach(row=>{const track=row.querySelector('.home-ad-track');track.addEventListener('scroll',()=>{const index=Math.round(track.scrollLeft/adSlideWidth(track));row.querySelectorAll('[data-ad-index]').forEach((b,i)=>{b.classList.toggle('selected',i===index);b.setAttribute('aria-pressed',String(i===index))})},{passive:true})})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-ad-index]');if(!b)return;const track=b.closest('.home-ad-row').querySelector('.home-ad-track');track.scrollTo({left:Number(b.dataset.adIndex)*adSlideWidth(track),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})});
document.addEventListener('click',e=>{const b=e.target.closest('[data-commercial-ad]');if(!b)return;const ad=commercialAds().find(a=>a.id===b.dataset.commercialAd);if(ad)openModal(`<h2>${ad.name}</h2><img src="${ad.content}" alt="${ad.name}" style="width:100%;border-radius:10px;margin-bottom:20px"><p class="muted">广告位展示示例，暂未接入商家链接。</p>`)});

function moveHomeAds(row,step){const track=row.querySelector('.home-ad-track'),max=Math.max(0,track.scrollWidth-track.clientWidth);const next=step>0?(track.scrollLeft>=max-2?0:Math.min(max,track.scrollLeft+adSlideWidth(track))):(track.scrollLeft<=2?max:Math.max(0,track.scrollLeft-adSlideWidth(track)));track.scrollTo({left:next,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function startHomeAds(){clearInterval(adTimer);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;adTimer=setInterval(()=>{if(document.hidden)return;document.querySelectorAll('.home-ad-row').forEach(row=>{const rect=row.getBoundingClientRect();if(rect.bottom>0&&rect.top<window.innerHeight&&!row.matches(':hover')&&!row.contains(document.activeElement))moveHomeAds(row,1)})},5000)}
document.addEventListener('click',e=>{const button=e.target.closest('[data-ad-step]');if(!button)return;moveHomeAds(button.closest('.home-ad-row'),Number(button.dataset.adStep))});
document.addEventListener('keydown',e=>{if(!e.target.matches('.home-ad-track')||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();moveHomeAds(e.target.closest('.home-ad-row'),e.key==='ArrowRight'?1:-1)});

function listingCards(items,withAd){const cards=items.map(card);if(withAd&&items.length)cards.splice(Math.min(7,cards.length),0,'<article class="listing-ad-card" aria-label="商业广告"><button type="button" class="listing-ad-cover" data-commercial-ad="audio" aria-label="查看音频好物广告"><img src="/assets/ads/list-audio.svg" alt="无线听觉，探索音频好物" width="300" height="400" loading="lazy"><span>广告</span></button><span class="card-title">探索音频好物</span><p class="card-meta">商业推广</p></article>');return cards.join('')}

document.addEventListener('click',e=>{const close=e.target.closest('[data-close-floating-ad]');if(!close)return;floatingAdClosed=true;close.closest('.home-floating-ad').remove()});

document.addEventListener('input',e=>{if(!e.target.matches('.filter-tag-search'))return;const body=e.target.closest('.filter-expanded-body'),query=e.target.value.trim().toLowerCase();let count=0;body.querySelectorAll('[data-filter]').forEach(b=>{b.hidden=!b.textContent.toLowerCase().includes(query);if(!b.hidden)count++});body.querySelector('.filter-no-match').hidden=count>0});

function closePlaybackSpeeds(){const panel=$('#speed-dropdown');if(panel)panel.remove();const button=$('[data-player-settings]');if(button)button.setAttribute('aria-expanded','false')}
function showPlaybackSpeeds(){
const player=$('#player');if(!player)return;if(player.querySelector('#speed-dropdown')){closePlaybackSpeeds();return}
const video=player.querySelector('video'),selected=video?video.playbackRate:Number(player.querySelector('.transport-speed').value);
player.querySelector('.player-settings').insertAdjacentHTML('beforeend',`<div class="speed-dropdown" id="speed-dropdown" role="group" aria-label="播放倍速">${[0.75,1,1.5].map(rate=>`<button type="button" data-playback-rate="${rate}" aria-pressed="${rate===selected}" class="${rate===selected?'selected':''}"><span class="speed-radio" aria-hidden="true"></span>${rate===1?'1.0':rate}x</button>`).join('')}</div>`);$('[data-player-settings]').setAttribute('aria-expanded','true');
}
document.addEventListener('click',e=>{if(e.target.closest('[data-player-settings]')){showPlaybackSpeeds();return}const option=e.target.closest('[data-playback-rate]');if(option){const rate=Number(option.dataset.playbackRate),player=$('#player');if(!player)return;player.querySelector('.transport-speed').value=String(rate);const video=player.querySelector('video');if(video)video.playbackRate=rate;closePlaybackSpeeds();$('[data-player-settings]').focus();return}if(!e.target.closest('.player-settings'))closePlaybackSpeeds()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#speed-dropdown')){closePlaybackSpeeds();$('[data-player-settings]').focus()}});

function closeLineMenu(){const panel=$('.line-dropdown');if(panel)panel.remove();const trigger=$('[data-action="线路"]');if(trigger)trigger.setAttribute('aria-expanded','false')}
function showLineMenu(){if($('.line-dropdown')){closeLineMenu();return}const bar=$('.action-bar');if(!bar)return;bar.insertAdjacentHTML('beforeend',`<div id="line-dropdown" class="speed-dropdown line-dropdown" role="group" aria-label="选择播放线路">${[1,2,3].map(n=>`<button type="button" data-line="${n}" aria-pressed="${selectedLine===n}" class="${selectedLine===n?'selected':''}"><span class="speed-radio" aria-hidden="true"></span>线路 ${n}</button>`).join('')}</div>`);$('[data-action="线路"]').setAttribute('aria-expanded','true')}
document.addEventListener('click',e=>{if(!e.target.closest('[data-action="线路"],.line-dropdown'))closeLineMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.line-dropdown')){closeLineMenu();$('[data-action="线路"]').focus()}});

function getLocalProfile(){
try{const saved=JSON.parse(localStorage.getItem('sa-local-profile')||'null');if(saved&&typeof saved.id==='string'&&typeof saved.nickname==='string'&&saved.nickname)return saved}catch{}
const words=['星河','晴空','晚风','云海','晨光','月影','青柠','暖阳'],names=['影迷','旅人','拾光者','观影家'];
const random=new Uint32Array(3);crypto.getRandomValues(random);
const profile={id:'WX'+random[0].toString(36).toUpperCase().padStart(7,'0'),nickname:words[random[1]%words.length]+names[random[2]%names.length]};
try{localStorage.setItem('sa-local-profile',JSON.stringify(profile))}catch{}
return profile;
}
function profilePage(){
const profile=getLocalProfile();
document.title='个人中心 - 万象';const item=(icon,label,href)=>`<a href="${href}"><span class="profile-menu-icon" aria-hidden="true">${icon}</span><span>${label}</span><span class="profile-chevron">›</span></a>`,service=(icon,label)=>`<button type="button" data-profile-service="${label}"><span class="profile-menu-icon" aria-hidden="true">${icon}</span><span>${label}</span><span class="profile-chevron">›</span></button>`;
$('#app').innerHTML=`<div class="profile-page"><section class="profile-top-ad">${homeAdRow(1)}</section><section class="profile-account"><div class="profile-avatar" aria-hidden="true">${esc(profile.nickname.slice(0,1))}</div><div><h1>${esc(profile.nickname)}</h1><p>ID：${esc(profile.id)}</p></div></section><nav class="profile-menu" aria-label="快捷服务">${service('<img src="/assets/invite-attachment.svg" width="20" height="20" alt="">','绑定邀请')}${item(accountIcon('clock'),'观看历史','/mine/history')}${item(accountIcon('bookmark'),'我的收藏','/mine/favorites')}</nav><section class="profile-main-ad">${homeAdRow(0)}</section><nav class="profile-menu" aria-label="我的服务">${service('<img src="/assets/stamping-service.svg" width="20" height="20" alt="">','商务合作')}${service('<img src="/assets/customer-group.svg" width="20" height="20" alt="">','官方群组')}${service('<img src="/assets/profile-share.svg" width="20" height="20" alt="">','分享推广')}${service('<img src="/assets/name-card.svg" width="20" height="20" alt="">','身份凭证')}${service('<img src="/assets/association.svg" width="20" height="20" alt="">','兑换功能')}</nav><nav class="profile-menu" aria-label="支持与设置"><button type="button" aria-label="客服"><span class="profile-menu-icon" aria-hidden="true"><img src="/assets/customer-service.svg" width="20" height="20" alt=""></span><span>客服</span><span class="profile-chevron">›</span></button>${service('<img src="/assets/profile-settings.svg" width="20" height="20" alt="">','设置')}</nav></div>`;initHomeAds();startHomeAds();
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-profile-service]');if(!button)return;const title=button.dataset.profileService;if(title==='官方群组'){showOfficialGroup();return}if(title==='商务合作'){showOfficialGroup(true);return}if(title==='身份凭证'){showIdentity();return}if(title==='兑换功能'){showRedeem();return}if(title==='分享推广'){navigate('/mine/share');return}if(title==='绑定邀请'){navigate('/mine/invite');return}if(title==='设置'){navigate('/mine/settings');return}openModal(`<h2>${esc(title)}</h2><p class="hint muted">此服务尚未接入，暂不可用。</p><button class="primary" data-action="close">知道了</button>`)});

function invitePage(){let bound='';try{bound=localStorage.getItem('sa-bound-invite')||''}catch{}document.title='绑定邀请码 - 万象';$('#app').innerHTML=`<div class="invite-page"><header class="invite-heading"><a href="/mine" aria-label="返回个人中心"><img class="page-back-icon" src="/assets/page-back.svg" width="24" height="24" alt=""></a><h1>绑定邀请码</h1></header><form id="invite-form" class="invite-card"><label class="sr-only" for="invite-code">绑定邀请码</label><input id="invite-code" name="invite" placeholder="绑定邀请码" value="${esc(bound)}" maxlength="20" autocomplete="off" autocapitalize="characters" spellcheck="false" ${bound?'disabled':''} aria-describedby="invite-note invite-error"><p id="invite-note">注：只能绑定一次，且绑定后不能进行修改</p><p id="invite-error" class="invite-error" role="alert" hidden></p><button type="submit" class="invite-submit" disabled>${bound?'已绑定':'确认绑定'}</button></form></div>`}
document.addEventListener('input',e=>{if(e.target.id!=='invite-code')return;const form=e.target.closest('form');form.querySelector('.invite-submit').disabled=!e.target.value.trim();e.target.removeAttribute('aria-invalid');form.querySelector('.invite-error').hidden=true});
document.addEventListener('submit',e=>{if(e.target.id!=='invite-form')return;e.preventDefault();const input=e.target.querySelector('input'),button=e.target.querySelector('button'),code=input.value.trim().toUpperCase();if(!code||input.disabled)return;if(code!=='WX2026'){input.setAttribute('aria-invalid','true');const error=e.target.querySelector('.invite-error');error.hidden=true;showInviteErrorToast();button.disabled=true;return}try{localStorage.setItem('sa-bound-invite',code)}catch{toast('无法保存，请检查浏览器存储设置');return}invitePage();toast('演示邀请码已绑定')});

