function showIdentity(){const user=getLocalProfile();openModal(`<section class="identity-card"><header class="identity-card-header"><img class="identity-brand" src="/assets/identity-brand.svg" alt="万象"><div class="identity-heading"><h2 id="identity-title">身份凭证</h2><span>万象 · 专属身份卡</span></div></header><div class="identity-user"><p class="identity-id">邀请码：${esc(user.id)}</p></div><div class="identity-code-section"><img class="identity-qr" src="/assets/identity-qr-demo.png" alt="设计稿示例二维码，不用于账号恢复"><p class="identity-warning">身份凭证卡请勿外泄他人</p><p class="identity-note">本机身份 · 二维码为展示示例</p></div><div class="identity-address-row"><div><span>永久地址</span><p class="identity-address">${esc(location.host)}</p></div><button class="identity-copy" data-identity-copy>复制</button></div><button class="identity-save" data-identity-save>保存凭证</button></section>`);const dialog=$('#modal');dialog.classList.add('identity-modal');dialog.setAttribute('aria-labelledby','identity-title');dialog.querySelector('.close-modal').innerHTML='<img src="/assets/official-group-close.svg" alt="">'}
document.addEventListener('click',async e=>{if(e.target.closest('[data-identity-copy]')){try{await navigator.clipboard.writeText(location.origin);toast('地址已复制')}catch{toast('复制失败，请手动复制地址')}}if(e.target.closest('[data-identity-save]')){const button=e.target.closest('button');button.disabled=true;try{const user=getLocalProfile(),canvas=document.createElement('canvas');canvas.width=560;canvas.height=780;const ctx=canvas.getContext('2d');ctx.fillStyle='#24262b';ctx.fillRect(0,0,560,780);ctx.textAlign='center';ctx.fillStyle='#ffac7b';ctx.font='bold 36px sans-serif';ctx.fillText('万象身份凭证',280,78);ctx.fillStyle='#ffffff';ctx.font='28px sans-serif';ctx.font='24px sans-serif';ctx.fillText('邀请码：'+user.id,280,148);const qr=new Image();qr.src='/assets/identity-qr-demo.png';await qr.decode();ctx.fillStyle='#fff';ctx.fillRect(164,222,232,232);ctx.drawImage(qr,176,234,208,208);ctx.fillStyle='#d4d6dc';ctx.font='24px sans-serif';ctx.fillText('身份凭证卡请勿外泄他人',280,514);ctx.fillStyle='#999fa9';ctx.font='20px sans-serif';ctx.fillText('本机身份 · 二维码为展示示例',280,560);ctx.fillText(location.origin,280,614,520);const link=document.createElement('a');link.download='万象身份凭证-'+user.id+'.png';link.href=canvas.toDataURL('image/png');link.click();toast('凭证已生成')}catch{toast('保存失败，请重试')}finally{button.disabled=false}}});

function settingsPage(){
 document.title='设置 - 万象';
 const row=(key,label,asset)=>`<button class="settings-row" data-setting="${key}"><img src="/assets/${asset}.svg" alt=""><span>${label}</span><span class="settings-chevron" aria-hidden="true">›</span></button>`;
 $('#app').innerHTML=`<div class="page personal-center settings-page"><header class="invite-heading"><a href="/mine" aria-label="返回个人中心"><img class="page-back-icon" src="/assets/page-back.svg" width="24" height="24" alt=""></a><h1>设置</h1></header><section class="settings-group" aria-label="账号设置">${row('password','设置账号密码','settings-password')}${row('recovery','账号找回','settings-recovery')}</section><section class="settings-group settings-cache" aria-label="缓存管理">${row('cache','清理缓存','settings-cache')}</section></div>`;
}
document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-setting]');if(!button)return;
 const setting=button.dataset.setting;
 if(setting==='cache'){showCacheConfirmation();return;}
 if(setting==='password'){navigate('/mine/settings/password');return;}
 if(setting==='recovery'){navigate('/mine/settings/recovery');return;}
 const title=setting==='password'?'设置账号密码':'账号找回';
 openModal(`<h2>${title}</h2><p class="hint muted">账号服务暂未接入，当前无法${setting==='password'?'设置账号密码':'找回账号'}。</p><button class="primary" data-action="close">知道了</button>`);
});

function showCacheConfirmation(){
 openModal(`<section class="cache-content"><h2 id="cache-title">清理缓存</h2><p id="cache-description">定期清除缓存，告别加载缓慢，<br>体验丝滑操作</p><div class="cache-art" aria-hidden="true"><img src="/assets/clear-cache.gif" width="120" height="120" alt=""></div><button class="official-group-copy" data-confirm-cache>确定</button></section>`);
 const dialog=$('#modal');dialog.classList.add('official-group-modal','cache-modal');dialog.setAttribute('aria-labelledby','cache-title');dialog.setAttribute('aria-describedby','cache-description');dialog.querySelector('.close-modal').innerHTML='<img src="/assets/cache-close.svg" alt="">';
}
document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-confirm-cache]');if(!button||button.disabled)return;
 button.disabled=true;button.textContent='清理中…';
 try{
  if('caches' in window){const keys=await caches.keys();const results=await Promise.all(keys.map(key=>caches.delete(key)));if(results.some(result=>!result))throw new Error('Cache removal failed');}
  if(button.isConnected)$('#modal').close();toast('缓存已清理');
 }catch{toast('清理失败，请稍后重试');}finally{button.disabled=false;button.textContent='确定';}
});

function accountPasswordPage(){
 document.title='设置账号密码 - 万象';
 $('#app').innerHTML=`<div class="page personal-center account-password-page"><header class="invite-heading"><a href="/mine/settings" aria-label="返回设置"><img class="page-back-icon" src="/assets/page-back.svg" width="24" height="24" alt=""></a><h1>设置账号密码</h1></header><div class="account-brand"><img src="/assets/account-brand.svg" alt="" width="80" height="30"></div><form id="account-password-form" novalidate><div class="account-fields"><div class="account-field"><label for="new-account">账号</label><input id="new-account" name="username" placeholder="账号4-10位、仅限英文、数字或组合" minlength="4" maxlength="10" autocomplete="username" autocapitalize="none" spellcheck="false" aria-describedby="account-format-error" required></div><div class="account-field"><label for="new-password">密码</label><input id="new-password" name="password" type="password" placeholder="密码6-8位，包含大小写字母和数字" minlength="6" maxlength="8" autocomplete="new-password" aria-describedby="account-format-error" required><button type="button" class="account-eye" data-password-visibility aria-label="显示密码" aria-pressed="false"><img src="/assets/account-eye-closed.png" width="18" height="18" alt=""></button></div></div><p id="account-format-error" class="account-format-error" role="alert" hidden></p><div class="account-password-note"><p>温馨提示：</p><p>1、不提供密码修改功能，请牢记自己的密码</p><p>2、请勿外泄密码</p></div><div class="account-submit-bar"><button type="submit" class="account-submit" disabled>确定</button></div></form></div>`;
}
function accountPasswordValid(form){return /^[a-zA-Z0-9]{4,10}$/.test(form.elements.username.value)&&/^(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9])[a-zA-Z0-9]{6,8}$/.test(form.elements.password.value)}
document.addEventListener('input',e=>{
 const form=e.target.closest('#account-password-form');if(!form)return;
 form.querySelector('.account-submit').disabled=!(form.elements.username.value.trim()&&form.elements.password.value);
 form.querySelector('.account-format-error').hidden=true;
});
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-password-visibility]');if(!button)return;
 const input=$('#new-password'),show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',show?'隐藏密码':'显示密码');button.querySelector('img').src=show?'/assets/account-eye.svg':'/assets/account-eye-closed.png';
});
document.addEventListener('submit',e=>{
 if(e.target.id!=='account-password-form')return;e.preventDefault();
 const error=e.target.querySelector('.account-format-error');
 error.textContent=accountPasswordValid(e.target)?'账号服务暂未接入，暂时无法设置，请稍后再试。':'请填写4–10位英文或数字账号，以及包含大小写字母和数字的6–8位密码。';error.hidden=false;
});

function accountRecoveryPage(){
 document.title='账号找回 - 万象';
 $('#app').innerHTML=`<div class="page personal-center recovery-page"><header class="invite-heading"><a href="/mine/settings" aria-label="返回设置"><img class="page-back-icon" src="/assets/page-back.svg" width="24" height="24" alt=""></a><h1>账号找回</h1></header><div class="recovery-tabs" role="tablist" aria-label="找回方式"><button id="recovery-qr-tab" role="tab" aria-selected="true" aria-controls="recovery-qr-panel" data-recovery-tab="qr">二维码凭证</button><button id="recovery-account-tab" role="tab" aria-selected="false" aria-controls="recovery-account-panel" data-recovery-tab="account">账号密码</button></div><form id="recovery-form"><section id="recovery-qr-panel" role="tabpanel" aria-labelledby="recovery-qr-tab"><div class="recovery-upload"><label class="recovery-upload-label" for="recovery-file"><span aria-hidden="true">+</span><span>点击上传身份凭证</span></label><input class="sr-only" id="recovery-file" type="file" accept="image/png,image/jpeg,image/webp"><div class="recovery-preview" hidden><img alt="身份凭证预览"><button type="button" data-recovery-remove aria-label="移除身份凭证">×</button></div></div></section><section id="recovery-account-panel" role="tabpanel" aria-labelledby="recovery-account-tab" hidden><div class="account-fields"><div class="account-field"><label for="recovery-account">账号</label><input id="recovery-account" name="username" placeholder="请输入账号" autocomplete="username" autocapitalize="none" spellcheck="false"></div><div class="account-field"><label for="recovery-password">密码</label><input id="recovery-password" name="password" type="password" placeholder="请输入密码" autocomplete="current-password"><button type="button" class="account-eye" data-recovery-eye aria-label="显示密码" aria-pressed="false"><img src="/assets/account-eye-closed.png" width="18" height="18" alt=""></button></div></div></section><p class="account-format-error" role="alert" hidden></p><div class="account-submit-bar"><button class="account-submit" type="submit" disabled>找回账号</button></div></form></div>`;
}
function recoveryUpdate(){const form=$('#recovery-form');if(!form)return;const qr=!$('#recovery-qr-panel').hidden;form.querySelector('.account-submit').disabled=qr?!form.querySelector('.recovery-preview img').getAttribute('src'):!(form.elements.username.value.trim()&&form.elements.password.value);form.querySelector('.account-submit').textContent=qr?'找回账号':'确定';}
function recoveryError(message){toast(message);const node=$('#toast');node.classList.add('invite-toast');node.setAttribute('role','alert');node.innerHTML='<span class="invite-toast-icon"><img src="/assets/invite-toast-cancel.svg" alt=""></span><span class="invite-toast-text">'+esc(message)+'</span>';}
document.addEventListener('click',e=>{
 const tab=e.target.closest('[data-recovery-tab]');if(tab){const qr=tab.dataset.recoveryTab==='qr';document.querySelectorAll('[data-recovery-tab]').forEach(button=>button.setAttribute('aria-selected',String(button===tab)));$('#recovery-qr-panel').hidden=!qr;$('#recovery-account-panel').hidden=qr;$('#recovery-form .account-format-error').hidden=true;recoveryUpdate();}
 const eye=e.target.closest('[data-recovery-eye]');if(eye){const input=$('#recovery-password'),show=input.type==='password';input.type=show?'text':'password';eye.setAttribute('aria-label',show?'隐藏密码':'显示密码');eye.setAttribute('aria-pressed',String(show));eye.querySelector('img').src=show?'/assets/account-eye.svg':'/assets/account-eye-closed.png';}
 if(e.target.closest('[data-recovery-remove]')){const form=$('#recovery-form');form.querySelector('.recovery-preview img').removeAttribute('src');form.querySelector('.recovery-preview').hidden=true;form.querySelector('.recovery-upload-label').hidden=false;$('#recovery-file').value='';recoveryUpdate();}
});
document.addEventListener('input',e=>{if(e.target.closest('#recovery-form'))recoveryUpdate()});
document.addEventListener('change',async e=>{
 if(e.target.id!=='recovery-file')return;const file=e.target.files[0];if(!file)return;const form=e.target.closest('form');
 if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>10*1024*1024){e.target.value='';recoveryError('请选择10MB以内的图片');return;}
 const preview=form.querySelector('.recovery-preview img'),reader=new FileReader();reader.onload=async()=>{if(!form.isConnected)return;preview.src=reader.result;try{await preview.decode();form.querySelector('.recovery-preview').hidden=false;form.querySelector('.recovery-upload-label').hidden=true;recoveryUpdate()}catch{preview.removeAttribute('src');e.target.value='';recoveryError('二维码解析失败');}};reader.onerror=()=>recoveryError('图片读取失败');reader.readAsDataURL(file);
});
document.addEventListener('submit',async e=>{
 if(e.target.id!=='recovery-form')return;e.preventDefault();const form=e.target,button=form.querySelector('.account-submit');if(button.disabled)return;button.disabled=true;
 try{if(!$('#recovery-qr-panel').hidden&&'BarcodeDetector' in window){const formats=await BarcodeDetector.getSupportedFormats();if(formats.includes('qr_code')){const results=await new BarcodeDetector({formats:['qr_code']}).detect(form.querySelector('.recovery-preview img'));if(!results.length){recoveryError('二维码解析失败');return;}}}
 const error=form.querySelector('.account-format-error');error.textContent='账号找回服务暂未接入，暂时无法验证身份并恢复账号。';error.hidden=false;
 }catch{recoveryError('二维码解析失败')}finally{recoveryUpdate()}
});

function showRedeem(){
 openModal(`<form id="redeem-form" class="redeem-content" novalidate><h2 id="redeem-title">兑换码</h2><label class="sr-only" for="redeem-code">兑换码</label><input id="redeem-code" name="code" placeholder="请输入兑换码" maxlength="64" autocomplete="off" autocapitalize="characters" spellcheck="false" aria-describedby="redeem-error"><p id="redeem-error" class="redeem-error" role="alert"></p><button class="redeem-confirm" type="submit" disabled>确认</button></form>`);
 const dialog=$('#modal');dialog.classList.add('official-group-modal','redeem-modal');dialog.setAttribute('aria-labelledby','redeem-title');dialog.querySelector('.close-modal').innerHTML='<img src="/assets/official-group-close.svg" alt="">';
}
document.addEventListener('input',e=>{
 if(e.target.id!=='redeem-code')return;
 const form=e.target.closest('form');form.querySelector('.redeem-confirm').disabled=!e.target.value.trim();form.querySelector('.redeem-error').textContent='';e.target.removeAttribute('aria-invalid');
});
document.addEventListener('submit',e=>{
 if(e.target.id!=='redeem-form')return;e.preventDefault();const form=e.target,input=form.elements.code,code=input.value.trim();if(!code)return;
 const invalid=!/^[a-zA-Z0-9-]+$/.test(code);
 form.querySelector('.redeem-error').textContent='兑换码不存在';
 if(invalid)input.setAttribute('aria-invalid','true');
 form.querySelector('.redeem-confirm').disabled=true;
});

function promotionLink(){const url=new URL('/',location.origin);url.searchParams.set('invite',getLocalProfile().id);return url.href;}
async function promotionPage(){
 const profile=getLocalProfile();document.title='分享推广 - 万象';
 $('#app').innerHTML=`<div class="page personal-center promotion-page"><header class="invite-heading"><a href="/mine" aria-label="返回个人中心"><img class="page-back-icon" src="/assets/page-back.svg" width="24" height="24" alt=""></a><h1>分享推广</h1><a class="promotion-records" href="/mine/invitations">邀请记录</a></header><div class="promotion-poster"><img id="promotion-image" alt="万象身份凭证，邀请码：${esc(profile.id)}。扫描二维码访问分享链接。" hidden><p class="promotion-loading" role="status">正在生成专属海报…</p></div><div class="promotion-note"><p>提示：</p><p>如果你推荐的好友没有成功绑定你的邀请码，请<span role="button" tabindex="0" data-promotion-copy="code">复制邀请码</span>发送给好友，好友填写在【我的】—【绑定邀请】中，即可确认推荐关系。</p></div><div class="promotion-actions"><button type="button" data-promotion-copy="link">复制链接</button><button type="button" class="promotion-save" data-promotion-save disabled>保存图片</button></div></div>`;
 const page=$('.promotion-page');
 try{
  const source=new Image();source.src='/assets/share-background.png';await source.decode();
  const brand=new Image();brand.src='/assets/identity-brand.svg';await brand.decode();
  const canvas=document.createElement('canvas');canvas.width=750;canvas.height=1040;const ctx=canvas.getContext('2d');ctx.drawImage(source,0,0,750,1040);
  ctx.fillStyle='#ffffff66';ctx.beginPath();ctx.roundRect(30,138,690,780,20);ctx.fill();
  ctx.fillStyle='#ffffff';ctx.beginPath();ctx.roundRect(40,148,670,760,16);ctx.fill();
  ctx.drawImage(brand,303,66,144,144);ctx.textAlign='center';ctx.fillStyle='#202124';ctx.font='600 32px sans-serif';ctx.fillText('万象身份凭证',375,258);
  ctx.fillStyle='#ff7231';ctx.beginPath();ctx.roundRect(319,304,112,40,20);ctx.fill();ctx.fillStyle='#fff';ctx.font='25px sans-serif';ctx.fillText('邀请码',375,333);
  ctx.fillStyle='#303238';ctx.font='30px sans-serif';ctx.fillText(profile.id,375,392,600);
  const qr=qrcode(0,'M');qr.addData(promotionLink());qr.make();const count=qr.getModuleCount(),cell=Math.floor(352/(count+8)),size=(count+8)*cell,left=375-size/2,top=420;
  ctx.fillStyle='#fff';ctx.fillRect(left,top,size,size);ctx.fillStyle='#111';for(let row=0;row<count;row++)for(let col=0;col<count;col++)if(qr.isDark(row,col))ctx.fillRect(left+(col+4)*cell,top+(row+4)*cell,cell,cell);
  ctx.fillStyle='#85858c';ctx.font='26px sans-serif';ctx.fillText('分享万象给好友，一起发现更多精彩',375,817,620);ctx.font='24px sans-serif';ctx.fillText('官网地址：'+location.origin,375,871,620);
  if(!page.isConnected)return;const img=page.querySelector('#promotion-image');img.src=canvas.toDataURL('image/png');img.hidden=false;page.querySelector('.promotion-loading').remove();page.querySelector('[data-promotion-save]').disabled=false;
 }catch{if(page.isConnected)page.querySelector('.promotion-loading').textContent='海报生成失败，请刷新重试';}
}
