function themeCategory(block,index){
 const items=block.items.map(m=>movies.find(x=>x.name===m.name)||m);
 return `<section class="catalog-section theme-category"><div class="section-title">${block.icon?`<img src="${esc(block.icon)}" alt="">`:''}<h2>${esc(block.name)}</h2></div><div class="movie-grid theme-category-grid" id="theme-category-${index}">${items.map((item,i)=>`<div class="theme-category-item" ${i>=6?'hidden':''}>${card(item)}</div>`).join('')}</div>${items.length>6?`<button type="button" class="theme-category-more" data-theme-more="theme-category-${index}" aria-controls="theme-category-${index}" aria-expanded="false">查看更多 <span aria-hidden="true">⌄</span></button>`:''}</section>`;
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-theme-more]');if(!button)return;const grid=document.getElementById(button.dataset.themeMore);if(!grid)return;const expanded=button.getAttribute('aria-expanded')!=='true';[...grid.children].forEach((item,index)=>item.hidden=!expanded&&index>=6);button.setAttribute('aria-expanded',String(expanded));button.innerHTML=expanded?'收起 <span aria-hidden="true">⌃</span>':'查看更多 <span aria-hidden="true">⌄</span>';});

function themeAllContent(topic){
 const seen=new Set(),items=topic.blocks.flatMap(block=>block.items).map(item=>movies.find(movie=>movie.name===item.name)||item).filter(item=>{const key=item.id||item.name;if(seen.has(key))return false;seen.add(key);return true;});
 const others=catalog.themes.filter(item=>item.id!==topic.id);
 return `<section class="catalog-section theme-category"><div class="movie-grid theme-category-grid">${items.map(card).join('')}</div></section><section class="theme-other-topics" aria-labelledby="other-topics-title"><h2 id="other-topics-title">其他专题</h2><nav aria-label="其他专题">${others.map(item=>`<a href="/theme-detail/${esc(item.id)}">${esc(item.name)}<span aria-hidden="true">›</span></a>`).join('')}</nav></section>`;
}
